INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000600', 'Petrofisika adalah ilmu yang mempelajari sifat fisik batuan dan fluida reservoir dengan tujuan utama...', 'Petrophysics is the study of the physical properties of reservoir rocks and fluids with the main purpose of...', 'option', 'PFC000000001', 'Soal Inisialisasi', 'a:4:{i:0;s:28:"Menentukan harga jual minyak";i:1;s:47:"Menghitung cadangan dan karakterisasi reservoir";i:2;s:25:"Merancang pompa permukaan";i:3;s:22:"Mengatur jadwal ekspor";}', 'a:4:{i:0;s:36:"Determining the selling price of oil";i:1;s:53:"Calculating reserves and characterizing the reservoir";i:2;s:23:"Designing surface pumps";i:3;s:25:"Managing export schedules";}', '', 'Menghitung cadangan dan karakterisasi reservoir', 'Calculating reserves and characterizing the reservoir', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000601', 'Porositas batuan umumnya dinyatakan dalam satuan...', 'Rock porosity is generally expressed in units of...', 'option', 'PFC000000001', 'Soal Inisialisasi', 'a:4:{i:0;s:18:"Fraksi atau persen";i:1;s:3:"psi";i:2;s:2:"mD";i:3;s:11:"Derajat API";}', 'a:4:{i:0;s:19:"Fraction or percent";i:1;s:3:"psi";i:2;s:2:"mD";i:3;s:11:"API degrees";}', '', 'Fraksi atau persen', 'Fraction or percent', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000602', 'Porositas 20% termasuk kategori kualitas...', 'A porosity of 20% falls into the quality category...', 'option', 'PFC000000001', 'Soal Inisialisasi', 'a:4:{i:0;s:12:"Sangat buruk";i:1;s:5:"Buruk";i:2;s:11:"Baik (good)";i:3;s:13:"Tidak terukur";}', 'a:4:{i:0;s:9:"Very poor";i:1;s:4:"Poor";i:2;s:4:"Good";i:3;s:12:"Unmeasurable";}', '', 'Baik (good)', 'Good', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000603', 'Syarat utama agar batuan dapat disebut batuan reservoir adalah memiliki...', 'The main requirement for a rock to be called a reservoir rock is that it has...', 'option', 'PFC000000001', 'Soal Inisialisasi', 'a:4:{i:0;s:22:"Warna terang dan keras";i:1;s:68:"Porositas untuk menyimpan dan permeabilitas untuk mengalirkan fluida";i:2;s:29:"Kandungan lempung yang tinggi";i:3;s:26:"Berat jenis di atas 3 g/cc";}', 'a:4:{i:0;s:27:"A bright color and hardness";i:1;s:54:"Porosity to store fluids and permeability to flow them";i:2;s:19:"A high clay content";i:3;s:31:"A specific gravity above 3 g/cc";}', '', 'Porositas untuk menyimpan dan permeabilitas untuk mengalirkan fluida', 'Porosity to store fluids and permeability to flow them', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000604', 'Porositas yang terbentuk selama proses pengendapan sedimen disebut porositas...', 'Porosity formed during the sediment deposition process is called...', 'option', 'PFC000000001', 'Soal Inisialisasi', 'a:4:{i:0;s:8:"Sekunder";i:1;s:6:"Primer";i:2;s:7:"Fraktur";i:3;s:5:"Vuggy";}', 'a:4:{i:0;s:9:"Secondary";i:1;s:7:"Primary";i:2;s:8:"Fracture";i:3;s:5:"Vuggy";}', '', 'Primer', 'Primary', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000605', 'Satuan permeabilitas dalam sistem Darcy adalah...', 'The unit of permeability in the Darcy system is...', 'option', 'PFC000000001', 'Soal Inisialisasi', 'a:4:{i:0;s:20:"Darcy atau miliDarcy";i:1;s:6:"Pascal";i:2;s:6:"Persen";i:3;s:7:"gram/cc";}', 'a:4:{i:0;s:19:"Darcy or milliDarcy";i:1;s:6:"Pascal";i:2;s:7:"Percent";i:3;s:7:"gram/cc";}', '', 'Darcy atau miliDarcy', 'Darcy or milliDarcy', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000606', 'Bagian reservoir yang produktif mengalirkan hidrokarbon disebut...', 'The productive part of a reservoir that flows hydrocarbons is called...', 'option', 'PFC000000001', 'Soal Inisialisasi', 'a:4:{i:0;s:7:"Net pay";i:1;s:15:"Gross thickness";i:2;s:10:"Overburden";i:3;s:13:"Shale barrier";}', 'a:4:{i:0;s:7:"Net pay";i:1;s:15:"Gross thickness";i:2;s:10:"Overburden";i:3;s:13:"Shale barrier";}', '', 'Net pay', 'Net pay', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000607', 'Manakah yang termasuk komponen penyusun batuan reservoir?', 'Which of the following are components of a reservoir rock?', 'multi', 'PFC000000001', 'Soal Inisialisasi', 'a:4:{i:0;s:14:"Matriks batuan";i:1;s:10:"Ruang pori";i:2;s:19:"Fluida pengisi pori";i:3;s:19:"Pipa selubung sumur";}', 'a:4:{i:0;s:11:"Rock matrix";i:1;s:10:"Pore space";i:2;s:23:"Fluid filling the pores";i:3;s:11:"Well casing";}', '', 'a:3:{i:0;s:14:"Matriks batuan";i:1;s:10:"Ruang pori";i:2;s:19:"Fluida pengisi pori";}', 'a:3:{i:0;s:11:"Rock matrix";i:1;s:10:"Pore space";i:2;s:23:"Fluid filling the pores";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000608', 'Urutkan proses pembentukan batuan sedimen dari awal sampai akhir.', 'Arrange the sedimentary rock formation process from beginning to end.', 'drag', 'PFC000000001', 'Soal Inisialisasi', 'a:5:{i:0;s:19:"Pelapukan dan erosi";i:1;s:20:"Transportasi sedimen";i:2;s:11:"Pengendapan";i:3;s:22:"Kompaksi dan sementasi";i:4;s:12:"Metamorfisme";}', 'a:5:{i:0;s:22:"Weathering and erosion";i:1;s:18:"Sediment transport";i:2;s:10:"Deposition";i:3;s:26:"Compaction and cementation";i:4;s:12:"Metamorphism";}', '', 'a:4:{i:0;s:19:"Pelapukan dan erosi";i:1;s:20:"Transportasi sedimen";i:2;s:11:"Pengendapan";i:3;s:22:"Kompaksi dan sementasi";}', 'a:4:{i:0;s:22:"Weathering and erosion";i:1;s:18:"Sediment transport";i:2;s:10:"Deposition";i:3;s:26:"Compaction and cementation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000609', 'Benarkah petrofisika hanya dibutuhkan pada fase produksi, tidak pada fase eksplorasi?', 'Is it true that petrophysics is only needed in the production phase, not in the exploration phase?', 'yesorno', 'PFC000000001', 'Soal Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000610', 'Sebuah core memiliki bulk volume 100 cm³ dan grain volume 75 cm³. Berapa porositas batuan tersebut?', 'A core has a bulk volume of 100 cm³ and a grain volume of 75 cm³. What is the porosity of the rock?', 'option', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:3:"15%";i:1;s:3:"20%";i:2;s:3:"25%";i:3;s:3:"33%";}', 'a:4:{i:0;s:3:"15%";i:1;s:3:"20%";i:2;s:3:"25%";i:3;s:3:"33%";}', '', '25%', '25%', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000611', 'Batuan memiliki porositas total 30% dan saturasi air 40%. Berapa volume hidrokarbon per 1 m³ batuan?', 'A rock has a total porosity of 30% and a water saturation of 40%. What is the hydrocarbon volume per 1 m³ of rock?', 'option', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:8:"0,12 m³";i:1;s:8:"0,18 m³";i:2;s:8:"0,30 m³";i:3;s:8:"0,40 m³";}', 'a:4:{i:0;s:8:"0.12 m³";i:1;s:8:"0.18 m³";i:2;s:8:"0.30 m³";i:3;s:8:"0.40 m³";}', '', '0,18 m³', '0.18 m³', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000612', 'Diketahui bulk density 2,35 g/cc, densitas matriks 2,65 g/cc, dan densitas fluida 1,00 g/cc. Berapa porositas berdasarkan persamaan densitas?', 'Given a bulk density of 2.35 g/cc, a matrix density of 2.65 g/cc, and a fluid density of 1.00 g/cc. What is the density-derived porosity?', 'option', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:5:"11,3%";i:1;s:5:"18,2%";i:2;s:5:"25,0%";i:3;s:5:"30,0%";}', 'a:4:{i:0;s:5:"11.3%";i:1;s:5:"18.2%";i:2;s:5:"25.0%";i:3;s:5:"30.0%";}', '', '18,2%', '18.2%', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000613', 'Pada batuan karbonat, porositas yang terbentuk dari lubang pelarutan berukuran besar disebut...', 'In carbonate rocks, porosity formed by large dissolution cavities is called...', 'option', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:22:"Intergranular porosity";i:1;s:14:"Vuggy porosity";i:2;s:25:"Intercrystalline porosity";i:3;s:13:"Microporosity";}', 'a:4:{i:0;s:22:"Intergranular porosity";i:1;s:14:"Vuggy porosity";i:2;s:25:"Intercrystalline porosity";i:3;s:13:"Microporosity";}', '', 'Vuggy porosity', 'Vuggy porosity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000614', 'Peningkatan intensitas sementasi pada batupasir umumnya menyebabkan...', 'Increasing cementation intensity in sandstone generally causes...', 'option', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:35:"Porositas dan permeabilitas menurun";i:1;s:35:"Porositas naik, permeabilitas turun";i:2;s:35:"Porositas turun, permeabilitas naik";i:3;s:22:"Keduanya tidak berubah";}', 'a:4:{i:0;s:42:"Both porosity and permeability to decrease";i:1;s:49:"Porosity to increase and permeability to decrease";i:2;s:49:"Porosity to decrease and permeability to increase";i:3;s:17:"Neither to change";}', '', 'Porositas dan permeabilitas menurun', 'Both porosity and permeability to decrease', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000615', 'Rasio net-to-gross (NTG) digunakan untuk...', 'The net-to-gross (NTG) ratio is used to...', 'option', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:26:"Mengoreksi densitas fluida";i:1;s:61:"Memisahkan ketebalan produktif dari total ketebalan reservoir";i:2;s:27:"Menghitung laju injeksi air";i:3;s:28:"Menentukan jenis semen sumur";}', 'a:4:{i:0;s:21:"Correct fluid density";i:1;s:60:"Separate productive thickness from total reservoir thickness";i:2;s:30:"Calculate water injection rate";i:3;s:33:"Determine the type of well cement";}', '', 'Memisahkan ketebalan produktif dari total ketebalan reservoir', 'Separate productive thickness from total reservoir thickness', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000616', 'Kehadiran lempung pada batupasir terutama menurunkan porositas efektif karena...', 'The presence of clay in sandstone mainly reduces effective porosity because...', 'option', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:38:"Lempung menambah volume butiran kuarsa";i:1;s:55:"Air terikat pada permukaan lempung menempati ruang pori";i:2;s:50:"Lempung meningkatkan densitas matriks secara tetap";i:3;s:29:"Lempung menghilangkan rekahan";}', 'a:4:{i:0;s:29:"Clay adds quartz grain volume";i:1;s:48:"Water bound to clay surfaces occupies pore space";i:2;s:39:"Clay increases matrix density uniformly";i:3;s:22:"Clay removes fractures";}', '', 'Air terikat pada permukaan lempung menempati ruang pori', 'Water bound to clay surfaces occupies pore space', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000617', 'Tortuositas yang tinggi pada jalur aliran fluida akan...', 'High tortuosity in the fluid flow path will...', 'option', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:26:"Meningkatkan permeabilitas";i:1;s:24:"Menurunkan permeabilitas";i:2;s:31:"Tidak memengaruhi permeabilitas";i:3;s:25:"Menaikkan porositas total";}', 'a:4:{i:0;s:21:"Increase permeability";i:1;s:21:"Decrease permeability";i:2;s:23:"Not affect permeability";i:3;s:23:"Increase total porosity";}', '', 'Menurunkan permeabilitas', 'Decrease permeability', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000618', 'Batuan dengan porositas 6% dan permeabilitas 0,05 mD paling tepat dikategorikan sebagai...', 'A rock with 6% porosity and 0.05 mD permeability is best categorized as...', 'option', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:39:"Reservoir konvensional berkualitas baik";i:1;s:32:"Reservoir tight (kualitas buruk)";i:2;s:27:"Reservoir karbonat berongga";i:3;s:37:"Reservoir dengan permeabilitas tinggi";}', 'a:4:{i:0;s:37:"A good-quality conventional reservoir";i:1;s:32:"A tight (poor-quality) reservoir";i:2;s:27:"A vuggy carbonate reservoir";i:3;s:29:"A high-permeability reservoir";}', '', 'Reservoir tight (kualitas buruk)', 'A tight (poor-quality) reservoir', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000619', 'Porositas sekunder pada batuan karbonat umumnya terbentuk akibat...', 'Secondary porosity in carbonate rocks generally forms as a result of...', 'option', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:34:"Pemadatan sedimen saat pengendapan";i:1;s:47:"Proses pelarutan (dissolution) dan dolomitisasi";i:2;s:29:"Pemilahan butir yang sempurna";i:3;s:41:"Pengangkatan batuan tanpa perubahan kimia";}', 'a:4:{i:0;s:37:"Sediment compaction during deposition";i:1;s:40:"Dissolution processes and dolomitization";i:2;s:21:"Perfect grain sorting";i:3;s:30:"Uplift without chemical change";}', '', 'Proses pelarutan (dissolution) dan dolomitisasi', 'Dissolution processes and dolomitization', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000620', 'Rekahan (fracture) pada reservoir karbonat umumnya memberikan kontribusi terbesar terhadap...', 'Fractures in a carbonate reservoir generally contribute most to...', 'option', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:15:"Porositas total";i:1;s:21:"Permeabilitas efektif";i:2;s:16:"Densitas matriks";i:3;s:20:"Saturasi air terikat";}', 'a:4:{i:0;s:14:"Total porosity";i:1;s:22:"Effective permeability";i:2;s:14:"Matrix density";i:3;s:28:"Irreducible water saturation";}', '', 'Permeabilitas efektif', 'Effective permeability', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000621', 'Data tekanan reservoir paling andal digunakan untuk menentukan...', 'Reservoir pressure data are most reliably used to determine...', 'option', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:33:"Kontak fluida seperti GOC dan WOC";i:1;s:25:"Kandungan mineral lempung";i:2;s:22:"Porositas total batuan";i:3;s:17:"Kadar air terikat";}', 'a:4:{i:0;s:34:"Fluid contacts such as GOC and WOC";i:1;s:20:"Clay mineral content";i:2;s:19:"Total rock porosity";i:3;s:19:"Bound water content";}', '', 'Kontak fluida seperti GOC dan WOC', 'Fluid contacts such as GOC and WOC', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000622', 'Manakah data yang diperlukan untuk perhitungan volumetrik cadangan hidrokarbon (OOIP)?', 'Which data are required for the volumetric calculation of hydrocarbon reserves (OOIP)?', 'multi', 'PFC000000001', 'Final Test Advanced', 'a:5:{i:0;s:19:"Luas area (acreage)";i:1;s:17:"Ketebalan net pay";i:2;s:9:"Porositas";i:3;s:20:"Saturasi hidrokarbon";i:4;s:30:"Faktor volumetrik formasi (Bo)";}', 'a:5:{i:0;s:22:"Areal extent (acreage)";i:1;s:17:"Net pay thickness";i:2;s:8:"Porosity";i:3;s:22:"Hydrocarbon saturation";i:4;s:28:"Formation volume factor (Bo)";}', '', 'a:5:{i:0;s:19:"Luas area (acreage)";i:1;s:17:"Ketebalan net pay";i:2;s:9:"Porositas";i:3;s:20:"Saturasi hidrokarbon";i:4;s:30:"Faktor volumetrik formasi (Bo)";}', 'a:5:{i:0;s:22:"Areal extent (acreage)";i:1;s:17:"Net pay thickness";i:2;s:8:"Porosity";i:3;s:22:"Hydrocarbon saturation";i:4;s:28:"Formation volume factor (Bo)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000623', 'Manakah pernyataan yang benar tentang porositas efektif?', 'Which statements about effective porosity are correct?', 'multi', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:41:"Hanya mencakup pori yang saling terhubung";i:1;s:39:"Selalu lebih besar dari porositas total";i:2;s:40:"Dipengaruhi oleh sementasi dan pemadatan";i:3;s:50:"Menjadi acuan utama perhitungan volume hidrokarbon";}', 'a:4:{i:0;s:37:"It includes only interconnected pores";i:1;s:39:"It is always larger than total porosity";i:2;s:44:"It is affected by cementation and compaction";i:3;s:59:"It is the main reference for hydrocarbon volume calculation";}', '', 'a:3:{i:0;s:41:"Hanya mencakup pori yang saling terhubung";i:1;s:40:"Dipengaruhi oleh sementasi dan pemadatan";i:2;s:50:"Menjadi acuan utama perhitungan volume hidrokarbon";}', 'a:3:{i:0;s:37:"It includes only interconnected pores";i:1;s:44:"It is affected by cementation and compaction";i:2;s:59:"It is the main reference for hydrocarbon volume calculation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000624', 'Manakah yang merupakan keterbatasan analisis core dalam petrofisika?', 'Which of the following are limitations of core analysis in petrophysics?', 'multi', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:46:"Sampel hanya mewakili sebagian kecil reservoir";i:1;s:33:"Kerusakan sampel saat pengambilan";i:2;s:53:"Ketidaksesuaian kondisi laboratorium dengan reservoir";i:3;s:44:"Core analysis tidak dapat mengukur porositas";}', 'a:4:{i:0;s:56:"The sample represents only a small part of the reservoir";i:1;s:29:"Sample damage during recovery";i:2;s:54:"Laboratory conditions differ from reservoir conditions";i:3;s:37:"Core analysis cannot measure porosity";}', '', 'a:3:{i:0;s:46:"Sampel hanya mewakili sebagian kecil reservoir";i:1;s:33:"Kerusakan sampel saat pengambilan";i:2;s:53:"Ketidaksesuaian kondisi laboratorium dengan reservoir";}', 'a:3:{i:0;s:56:"The sample represents only a small part of the reservoir";i:1;s:29:"Sample damage during recovery";i:2;s:54:"Laboratory conditions differ from reservoir conditions";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000625', 'Manakah ciri khas reservoir karbonat dibandingkan batupasir?', 'Which are characteristic features of carbonate reservoirs compared with sandstones?', 'multi', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:56:"Porositas dapat terbentuk setelah pengendapan (sekunder)";i:1;s:41:"Distribusi porositas sering tidak homogen";i:2;s:29:"Rekahan dan vug umum dijumpai";i:3;s:42:"Selalu memiliki permeabilitas lebih tinggi";}', 'a:4:{i:0;s:46:"Porosity can form after deposition (secondary)";i:1;s:44:"Porosity distribution is often heterogeneous";i:2;s:29:"Fractures and vugs are common";i:3;s:31:"Always have higher permeability";}', '', 'a:3:{i:0;s:56:"Porositas dapat terbentuk setelah pengendapan (sekunder)";i:1;s:41:"Distribusi porositas sering tidak homogen";i:2;s:29:"Rekahan dan vug umum dijumpai";}', 'a:3:{i:0;s:46:"Porosity can form after deposition (secondary)";i:1;s:44:"Porosity distribution is often heterogeneous";i:2;s:29:"Fractures and vugs are common";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000626', 'Urutkan tahapan diagenesis yang menurunkan kualitas reservoir dari yang paling awal.', 'Arrange the diagenetic stages that reduce reservoir quality from the earliest.', 'drag', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:16:"Kompaksi mekanik";i:1;s:9:"Sementasi";i:2;s:34:"Kompaksi kimia (pressure solution)";i:3;s:23:"Pelarutan (dissolution)";}', 'a:4:{i:0;s:21:"Mechanical compaction";i:1;s:11:"Cementation";i:2;s:39:"Chemical compaction (pressure solution)";i:3;s:11:"Dissolution";}', '', 'a:4:{i:0;s:16:"Kompaksi mekanik";i:1;s:9:"Sementasi";i:2;s:34:"Kompaksi kimia (pressure solution)";i:3;s:23:"Pelarutan (dissolution)";}', 'a:4:{i:0;s:21:"Mechanical compaction";i:1;s:11:"Cementation";i:2;s:39:"Chemical compaction (pressure solution)";i:3;s:11:"Dissolution";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000627', 'Urutkan skala ukuran pori dari yang terkecil ke terbesar.', 'Arrange pore size scales from smallest to largest.', 'drag', 'PFC000000001', 'Final Test Advanced', 'a:4:{i:0;s:19:"Mikropori (< 1 µm)";i:1;s:21:"Mesopori (1 - 10 µm)";i:2;s:20:"Makropori (> 10 µm)";i:3;s:12:"Vug (> 1 mm)";}', 'a:4:{i:0;s:19:"Micropore (< 1 µm)";i:1;s:21:"Mesopore (1 - 10 µm)";i:2;s:20:"Macropore (> 10 µm)";i:3;s:12:"Vug (> 1 mm)";}', '', 'a:4:{i:0;s:19:"Mikropori (< 1 µm)";i:1;s:21:"Mesopori (1 - 10 µm)";i:2;s:20:"Makropori (> 10 µm)";i:3;s:12:"Vug (> 1 mm)";}', 'a:4:{i:0;s:19:"Micropore (< 1 µm)";i:1;s:21:"Mesopore (1 - 10 µm)";i:2;s:20:"Macropore (> 10 µm)";i:3;s:12:"Vug (> 1 mm)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000628', 'Benarkah porositas efektif selalu lebih kecil atau sama dengan porositas total?', 'Is it true that effective porosity is always less than or equal to total porosity?', 'yesorno', 'PFC000000001', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000629', 'Benarkah batuan dengan porositas tinggi pasti memiliki permeabilitas tinggi?', 'Is it true that a rock with high porosity must have high permeability?', 'yesorno', 'PFC000000001', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000630', 'Permeabilitas batuan adalah ukuran kemampuan batuan untuk...', 'Rock permeability is a measure of the rock''s ability to...', 'option', 'PFC000000002', 'Soal Inisialisasi', 'a:4:{i:0;s:16:"Menyimpan fluida";i:1;s:18:"Mengalirkan fluida";i:2;s:26:"Menahan tekanan overburden";i:3;s:14:"Menyerap panas";}', 'a:4:{i:0;s:12:"Store fluids";i:1;s:11:"Flow fluids";i:2;s:29:"Withstand overburden pressure";i:3;s:11:"Absorb heat";}', '', 'Mengalirkan fluida', 'Flow fluids', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000631', 'Satuan yang paling umum dipakai untuk permeabilitas batuan reservoir adalah...', 'The most common unit used for reservoir rock permeability is...', 'option', 'PFC000000002', 'Soal Inisialisasi', 'a:4:{i:0;s:14:"miliDarcy (mD)";i:1;s:3:"psi";i:2;s:7:"gram/cc";i:3;s:1:"%";}', 'a:4:{i:0;s:15:"milliDarcy (mD)";i:1;s:3:"psi";i:2;s:7:"gram/cc";i:3;s:1:"%";}', '', 'miliDarcy (mD)', 'milliDarcy (mD)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000632', 'Permeabilitas absolut diukur ketika batuan dijenuhi oleh...', 'Absolute permeability is measured when the rock is saturated with...', 'option', 'PFC000000002', 'Soal Inisialisasi', 'a:4:{i:0;s:20:"Dua fluida sekaligus";i:1;s:38:"Satu jenis fluida saja (100% saturasi)";i:2;s:21:"Gas dan air bersamaan";i:3;s:26:"Fluida dengan saturasi 50%";}', 'a:4:{i:0;s:18:"Two fluids at once";i:1;s:37:"A single fluid only (100% saturation)";i:2;s:22:"Gas and water together";i:3;s:25:"A fluid at 50% saturation";}', '', 'Satu jenis fluida saja (100% saturasi)', 'A single fluid only (100% saturation)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000633', 'Permeabilitas efektif adalah permeabilitas terhadap suatu fluida pada kondisi...', 'Effective permeability is the permeability to a given fluid under conditions of...', 'option', 'PFC000000002', 'Soal Inisialisasi', 'a:4:{i:0;s:13:"Batuan kosong";i:1;s:38:"Saturasi fluida tertentu di dalam pori";i:2;s:21:"Tekanan atmosfer saja";i:3;s:15:"Aliran turbulen";}', 'a:4:{i:0;s:13:"An empty rock";i:1;s:44:"A specific fluid saturation within the pores";i:2;s:25:"Atmospheric pressure only";i:3;s:14:"Turbulent flow";}', '', 'Saturasi fluida tertentu di dalam pori', 'A specific fluid saturation within the pores', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000634', 'Hukum Darcy menghubungkan laju alir fluida dengan...', 'Darcy''s law relates fluid flow rate to...', 'option', 'PFC000000002', 'Soal Inisialisasi', 'a:4:{i:0;s:47:"Gradien tekanan, luas penampang, dan viskositas";i:1;s:26:"Warna batuan dan porositas";i:2;s:20:"Kedalaman sumur saja";i:3;s:22:"Kadar lempung dan suhu";}', 'a:4:{i:0;s:54:"Pressure gradient, cross-sectional area, and viscosity";i:1;s:23:"Rock color and porosity";i:2;s:15:"Well depth only";i:3;s:28:"Clay content and temperature";}', '', 'Gradien tekanan, luas penampang, dan viskositas', 'Pressure gradient, cross-sectional area, and viscosity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000635', 'Batuan dengan permeabilitas 1 mD termasuk kategori...', 'A rock with 1 mD permeability falls into the category...', 'option', 'PFC000000002', 'Soal Inisialisasi', 'a:4:{i:0;s:13:"Sangat tinggi";i:1;s:6:"Rendah";i:2;s:20:"Sangat tinggi sekali";i:3;s:18:"Tidak dapat diukur";}', 'a:4:{i:0;s:9:"Very high";i:1;s:3:"Low";i:2;s:14:"Extremely high";i:3;s:12:"Unmeasurable";}', '', 'Rendah', 'Low', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000636', 'Pernyataan yang benar tentang hubungan porositas dan permeabilitas adalah...', 'The correct statement about the relationship between porosity and permeability is...', 'option', 'PFC000000002', 'Soal Inisialisasi', 'a:4:{i:0;s:52:"Porositas tinggi selalu berarti permeabilitas tinggi";i:1;s:42:"Keduanya tidak selalu berkorelasi langsung";i:2;s:47:"Permeabilitas selalu lebih besar dari porositas";i:3;s:29:"Keduanya selalu bernilai sama";}', 'a:4:{i:0;s:44:"High porosity always means high permeability";i:1;s:39:"They are not always directly correlated";i:2;s:44:"Permeability is always greater than porosity";i:3;s:21:"They are always equal";}', '', 'Keduanya tidak selalu berkorelasi langsung', 'They are not always directly correlated', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000637', 'Faktor apa saja yang memengaruhi permeabilitas batuan?', 'Which factors affect rock permeability?', 'multi', 'PFC000000002', 'Soal Inisialisasi', 'a:4:{i:0;s:12:"Ukuran butir";i:1;s:25:"Pemilahan (sorting) butir";i:2;s:17:"Tingkat sementasi";i:3;s:12:"Warna batuan";}', 'a:4:{i:0;s:10:"Grain size";i:1;s:13:"Grain sorting";i:2;s:21:"Degree of cementation";i:3;s:10:"Rock color";}', '', 'a:3:{i:0;s:12:"Ukuran butir";i:1;s:25:"Pemilahan (sorting) butir";i:2;s:17:"Tingkat sementasi";}', 'a:3:{i:0;s:10:"Grain size";i:1;s:13:"Grain sorting";i:2;s:21:"Degree of cementation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000638', 'Urutkan ukuran butir sedimen dari yang paling kasar ke paling halus.', 'Arrange sediment grain sizes from coarsest to finest.', 'drag', 'PFC000000002', 'Soal Inisialisasi', 'a:5:{i:0;s:16:"Kerikil (gravel)";i:1;s:18:"Pasir sangat kasar";i:2;s:11:"Pasir halus";i:3;s:12:"Lanau (silt)";i:4;s:14:"Lempung (clay)";}', 'a:5:{i:0;s:6:"Gravel";i:1;s:16:"Very coarse sand";i:2;s:9:"Fine sand";i:3;s:4:"Silt";i:4;s:4:"Clay";}', '', 'a:5:{i:0;s:16:"Kerikil (gravel)";i:1;s:18:"Pasir sangat kasar";i:2;s:11:"Pasir halus";i:3;s:12:"Lanau (silt)";i:4;s:14:"Lempung (clay)";}', 'a:5:{i:0;s:6:"Gravel";i:1;s:16:"Very coarse sand";i:2;s:9:"Fine sand";i:3;s:4:"Silt";i:4;s:4:"Clay";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000639', 'Benarkah permeabilitas absolut hanya bergantung pada sifat batuan, bukan pada jenis fluida yang mengalir?', 'Is it true that absolute permeability depends only on rock properties, not on the type of flowing fluid?', 'yesorno', 'PFC000000002', 'Soal Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000640', 'Aliran 10 cm³/s melewati core dengan luas 20 cm² dan panjang 10 cm pada beda tekanan 2 atm, viskositas 1 cp. Berapa permeabilitasnya?', 'A flow of 10 cm³/s passes through a core of 20 cm² area and 10 cm length at a pressure difference of 2 atm and viscosity of 1 cp. What is the permeability?', 'option', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:10:"0,25 Darcy";i:1;s:9:"2,5 Darcy";i:2;s:8:"25 Darcy";i:3;s:9:"250 Darcy";}', 'a:4:{i:0;s:10:"0.25 Darcy";i:1;s:9:"2.5 Darcy";i:2;s:8:"25 Darcy";i:3;s:9:"250 Darcy";}', '', '2,5 Darcy', '2.5 Darcy', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000641', 'Nilai 1 Darcy setara dengan...', 'A value of 1 Darcy is equivalent to...', 'option', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:21:"9,87 × 10⁻¹³ m²";i:1;s:20:"9,87 × 10⁻⁹ m²";i:2;s:16:"1 × 10⁻³ m²";i:3;s:19:"1 × 10⁻¹⁵ m²";}', 'a:4:{i:0;s:21:"9.87 × 10⁻¹³ m²";i:1;s:20:"9.87 × 10⁻⁹ m²";i:2;s:16:"1 × 10⁻³ m²";i:3;s:19:"1 × 10⁻¹⁵ m²";}', '', '9,87 × 10⁻¹³ m²', '9.87 × 10⁻¹³ m²', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000642', 'Efek Klinkenberg menyebabkan permeabilitas yang diukur dengan gas...', 'The Klinkenberg effect causes permeability measured with gas to be...', 'option', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:38:"Lebih rendah dari permeabilitas cairan";i:1;s:38:"Lebih tinggi dari permeabilitas cairan";i:2;s:39:"Sama persis dengan permeabilitas cairan";i:3;s:13:"Tidak terukur";}', 'a:4:{i:0;s:30:"Lower than liquid permeability";i:1;s:31:"Higher than liquid permeability";i:2;s:36:"Exactly equal to liquid permeability";i:3;s:12:"Unmeasurable";}', '', 'Lebih tinggi dari permeabilitas cairan', 'Higher than liquid permeability', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000643', 'Pada batuan berlapis (bedded), rasio permeabilitas vertikal terhadap horizontal (kv/kh) umumnya...', 'In bedded rocks, the ratio of vertical to horizontal permeability (kv/kh) is generally...', 'option', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:18:"Lebih besar dari 1";i:1;s:18:"Lebih kecil dari 1";i:2;s:20:"Selalu sama dengan 1";i:3;s:22:"Tidak dapat ditentukan";}', 'a:4:{i:0;s:14:"Greater than 1";i:1;s:11:"Less than 1";i:2;s:17:"Always equal to 1";i:3;s:23:"Impossible to determine";}', '', 'Lebih kecil dari 1', 'Less than 1', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000644', 'Pada kurva relative permeability, titik di mana kro dan krw berpotongan disebut...', 'On a relative permeability curve, the point where kro and krw intersect is called...', 'option', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:28:"Irreducible water saturation";i:1;s:15:"Crossover point";i:2;s:19:"Endpoint saturation";i:3;s:18:"Residual oil point";}', 'a:4:{i:0;s:28:"Irreducible water saturation";i:1;s:15:"Crossover point";i:2;s:19:"Endpoint saturation";i:3;s:18:"Residual oil point";}', '', 'Crossover point', 'Crossover point', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000645', 'Pada batuan water-wet, air cenderung menempati...', 'In a water-wet rock, water tends to occupy...', 'option', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:32:"Pori-pori besar di bagian tengah";i:1;s:30:"Pori kecil dan permukaan butir";i:2;s:13:"Hanya rekahan";i:3;s:22:"Rongga pelarutan besar";}', 'a:4:{i:0;s:25:"Large pores in the center";i:1;s:30:"Small pores and grain surfaces";i:2;s:14:"Fractures only";i:3;s:26:"Large dissolution cavities";}', '', 'Pori kecil dan permukaan butir', 'Small pores and grain surfaces', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000646', 'Bertambahnya tegangan efektif (effective stress) pada batuan reservoir umumnya menyebabkan...', 'Increasing effective stress in a reservoir rock generally causes...', 'option', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:35:"Porositas dan permeabilitas menurun";i:1;s:19:"Porositas meningkat";i:2;s:23:"Permeabilitas meningkat";i:3;s:19:"Tidak ada perubahan";}', 'a:4:{i:0;s:37:"Porosity and permeability to decrease";i:1;s:20:"Porosity to increase";i:2;s:24:"Permeability to increase";i:3;s:9:"No change";}', '', 'Porositas dan permeabilitas menurun', 'Porosity and permeability to decrease', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000647', 'Persamaan Kozeny-Carman menunjukkan bahwa permeabilitas berbanding lurus dengan...', 'The Kozeny-Carman equation shows that permeability is directly proportional to...', 'option', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:32:"Kuadrat diameter butir rata-rata";i:1;s:17:"Viskositas fluida";i:2;s:19:"Tegangan overburden";i:3;s:17:"Kadar air terikat";}', 'a:4:{i:0;s:37:"The square of the mean grain diameter";i:1;s:15:"Fluid viscosity";i:2;s:17:"Overburden stress";i:3;s:19:"Bound water content";}', '', 'Kuadrat diameter butir rata-rata', 'The square of the mean grain diameter', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000648', 'Rekahan pada reservoir tight umumnya berfungsi untuk...', 'Fractures in a tight reservoir generally serve to...', 'option', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:28:"Mengurangi porositas matriks";i:1;s:48:"Menyediakan jalur aliran berpermeabilitas tinggi";i:2;s:28:"Menurunkan tekanan reservoir";i:3;s:25:"Meningkatkan saturasi air";}', 'a:4:{i:0;s:22:"Reduce matrix porosity";i:1;s:36:"Provide high-permeability flow paths";i:2;s:25:"Reduce reservoir pressure";i:3;s:25:"Increase water saturation";}', '', 'Menyediakan jalur aliran berpermeabilitas tinggi', 'Provide high-permeability flow paths', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000649', 'Penambahan lempung pada batupasir menurunkan permeabilitas terutama karena...', 'Adding clay to sandstone reduces permeability mainly because...', 'option', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:47:"Lempung menyumbat pori dan menambah tortuositas";i:1;s:29:"Lempung menambah ukuran butir";i:2;s:38:"Lempung meningkatkan porositas efektif";i:3;s:25:"Lempung melarutkan kuarsa";}', 'a:4:{i:0;s:41:"Clay plugs pores and increases tortuosity";i:1;s:25:"Clay increases grain size";i:2;s:33:"Clay increases effective porosity";i:3;s:21:"Clay dissolves quartz";}', '', 'Lempung menyumbat pori dan menambah tortuositas', 'Clay plugs pores and increases tortuosity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000650', 'Hukum Darcy berlaku paling tepat pada kondisi aliran...', 'Darcy''s law applies most appropriately under conditions of...', 'option', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:7:"Laminer";i:1;s:8:"Turbulen";i:2;s:39:"Dua fase dengan viskositas tak terbatas";i:3;s:27:"Aliran melalui pipa terbuka";}', 'a:4:{i:0;s:7:"Laminar";i:1;s:9:"Turbulent";i:2;s:34:"Two-phase with unbounded viscosity";i:3;s:25:"Flow through an open pipe";}', '', 'Laminer', 'Laminar', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000651', 'Saturasi air ireduktibel (Swir) adalah saturasi air minimum yang...', 'Irreducible water saturation (Swir) is the minimum water saturation that...', 'option', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:34:"Masih dapat mengalir saat produksi";i:1;s:31:"Tidak dapat terproduksikan lagi";i:2;s:29:"Sama dengan saturasi air awal";i:3;s:19:"Selalu bernilai nol";}', 'a:4:{i:0;s:32:"Can still flow during production";i:1;s:25:"Can no longer be produced";i:2;s:35:"Equals the initial water saturation";i:3;s:14:"Is always zero";}', '', 'Tidak dapat terproduksikan lagi', 'Can no longer be produced', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000652', 'Manakah metode yang dapat digunakan untuk menentukan permeabilitas reservoir?', 'Which methods can be used to determine reservoir permeability?', 'multi', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:29:"Analisis core di laboratorium";i:1;s:21:"Uji sumur (well test)";i:2;s:22:"Korelasi dari data log";i:3;s:23:"Pengukuran warna batuan";}', 'a:4:{i:0;s:31:"Core analysis in the laboratory";i:1;s:12:"Well testing";i:2;s:25:"Correlation from log data";i:3;s:22:"Rock color measurement";}', '', 'a:3:{i:0;s:29:"Analisis core di laboratorium";i:1;s:21:"Uji sumur (well test)";i:2;s:22:"Korelasi dari data log";}', 'a:3:{i:0;s:31:"Core analysis in the laboratory";i:1;s:12:"Well testing";i:2;s:25:"Correlation from log data";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000653', 'Manakah pernyataan yang benar tentang relative permeability?', 'Which statements about relative permeability are correct?', 'multi', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:29:"Nilai berkisar antara 0 dan 1";i:1;s:31:"Bergantung pada saturasi fluida";i:2;s:30:"Dipengaruhi wettability batuan";i:3;s:41:"Selalu bernilai sama untuk air dan minyak";}', 'a:4:{i:0;s:32:"Its value ranges between 0 and 1";i:1;s:30:"It depends on fluid saturation";i:2;s:36:"It is influenced by rock wettability";i:3;s:36:"It is always equal for water and oil";}', '', 'a:3:{i:0;s:29:"Nilai berkisar antara 0 dan 1";i:1;s:31:"Bergantung pada saturasi fluida";i:2;s:30:"Dipengaruhi wettability batuan";}', 'a:3:{i:0;s:32:"Its value ranges between 0 and 1";i:1;s:30:"It depends on fluid saturation";i:2;s:36:"It is influenced by rock wettability";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000654', 'Manakah yang dapat menurunkan permeabilitas di sekitar lubang sumur (formation damage)?', 'Which of the following can reduce permeability around the wellbore (formation damage)?', 'multi', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:40:"Migrasi partikel halus (fines migration)";i:1;s:20:"Pembengkakan lempung";i:2;s:19:"Pengendapan scaling";i:3;s:29:"Peningkatan tekanan reservoir";}', 'a:4:{i:0;s:15:"Fines migration";i:1;s:13:"Clay swelling";i:2;s:16:"Scale deposition";i:3;s:29:"Increasing reservoir pressure";}', '', 'a:3:{i:0;s:40:"Migrasi partikel halus (fines migration)";i:1;s:20:"Pembengkakan lempung";i:2;s:19:"Pengendapan scaling";}', 'a:3:{i:0;s:15:"Fines migration";i:1;s:13:"Clay swelling";i:2;s:16:"Scale deposition";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000655', 'Manakah sifat fisik batuan yang termasuk parameter petrofisika dasar?', 'Which rock physical properties are basic petrophysical parameters?', 'multi', 'PFC000000002', 'Final Test Advanced', 'a:4:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:15:"Saturasi fluida";i:3;s:12:"Harga minyak";}', 'a:4:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:16:"Fluid saturation";i:3;s:9:"Oil price";}', '', 'a:3:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:15:"Saturasi fluida";}', 'a:3:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:16:"Fluid saturation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000656', 'Urutkan urutan pengukuran permeabilitas core di laboratorium dari tahap awal.', 'Arrange the laboratory core permeability measurement steps starting from the first stage.', 'drag', 'PFC000000002', 'Final Test Advanced', 'a:5:{i:0;s:23:"Pengambilan sampel core";i:1;s:34:"Pembersihan dan pengeringan sampel";i:2;s:31:"Penjenuhan sampel dengan fluida";i:3;s:37:"Pengukuran laju alir dan beda tekanan";i:4;s:30:"Perhitungan dengan hukum Darcy";}', 'a:5:{i:0;s:13:"Core sampling";i:1;s:26:"Sample cleaning and drying";i:2;s:32:"Saturating the sample with fluid";i:3;s:43:"Measuring flow rate and pressure difference";i:4;s:29:"Calculation using Darcy''s law";}', '', 'a:5:{i:0;s:23:"Pengambilan sampel core";i:1;s:34:"Pembersihan dan pengeringan sampel";i:2;s:31:"Penjenuhan sampel dengan fluida";i:3;s:37:"Pengukuran laju alir dan beda tekanan";i:4;s:30:"Perhitungan dengan hukum Darcy";}', 'a:5:{i:0;s:13:"Core sampling";i:1;s:26:"Sample cleaning and drying";i:2;s:32:"Saturating the sample with fluid";i:3;s:43:"Measuring flow rate and pressure difference";i:4;s:29:"Calculation using Darcy''s law";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
