INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000660', 'Viskositas fluida adalah ukuran...', 'Fluid viscosity is a measure of...', 'option', 'PFC000000003', 'Soal Inisialisasi', 'a:4:{i:0;s:54:"Kemampuan fluida mengalir (resistensi terhadap aliran)";i:1;s:26:"Kandungan gas dalam minyak";i:2;s:18:"Berat jenis fluida";i:3;s:27:"Tekanan fluida di reservoir";}', 'a:4:{i:0;s:51:"The ability of a fluid to flow (resistance to flow)";i:1;s:22:"The gas content in oil";i:2;s:33:"The specific gravity of the fluid";i:3;s:35:"The fluid pressure in the reservoir";}', '', 'Kemampuan fluida mengalir (resistensi terhadap aliran)', 'The ability of a fluid to flow (resistance to flow)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000661', 'Faktor volume formasi minyak (Bo) menyatakan...', 'The oil formation volume factor (Bo) expresses...', 'option', 'PFC000000003', 'Soal Inisialisasi', 'a:4:{i:0;s:68:"Perbandingan volume minyak di reservoir terhadap volume di permukaan";i:1;s:39:"Perbandingan volume gas terhadap minyak";i:2;s:22:"Kadar air dalam minyak";i:3;s:30:"Berat minyak per satuan volume";}', 'a:4:{i:0;s:69:"The ratio of oil volume in the reservoir to its volume at the surface";i:1;s:37:"The ratio of gas volume to oil volume";i:2;s:28:"The water content in the oil";i:3;s:33:"The weight of oil per unit volume";}', '', 'Perbandingan volume minyak di reservoir terhadap volume di permukaan', 'The ratio of oil volume in the reservoir to its volume at the surface', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
