INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000663', 'Bubble point pressure adalah tekanan ketika...', 'Bubble point pressure is the pressure at which...', 'option', 'PFC000000003', 'Soal Inisialisasi', 'a:4:{i:0;s:43:"Gas pertama kali keluar dari larutan minyak";i:1;s:17:"Air mulai menguap";i:2;s:14:"Minyak membeku";i:3;s:24:"Porositas batuan berubah";}', 'a:4:{i:0;s:39:"Gas first comes out of the oil solution";i:1;s:25:"Water starts to evaporate";i:2;s:11:"Oil freezes";i:3;s:21:"Rock porosity changes";}', '', 'Gas pertama kali keluar dari larutan minyak', 'Gas first comes out of the oil solution', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000664', 'Dew point pressure pada reservoir gas adalah tekanan ketika...', 'Dew point pressure in a gas reservoir is the pressure at which...', 'option', 'PFC000000003', 'Soal Inisialisasi', 'a:4:{i:0;s:34:"Gas mulai mengembun menjadi cairan";i:1;s:21:"Gas berhenti mengalir";i:2;s:21:"Air mulai terproduksi";i:3;s:20:"Minyak mulai menguap";}', 'a:4:{i:0;s:34:"Gas begins to condense into liquid";i:1;s:17:"Gas stops flowing";i:2;s:27:"Water begins to be produced";i:3;s:22:"Oil begins to vaporize";}', '', 'Gas mulai mengembun menjadi cairan', 'Gas begins to condense into liquid', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000665', 'Minyak dengan nilai API gravity tinggi umumnya bersifat...', 'Oil with a high API gravity value is generally...', 'option', 'PFC000000003', 'Soal Inisialisasi', 'a:4:{i:0;s:24:"Ringan dan kurang kental";i:1;s:23:"Berat dan sangat kental";i:2;s:31:"Selalu mengandung banyak sulfur";i:3;s:20:"Tidak dapat mengalir";}', 'a:4:{i:0;s:22:"Light and less viscous";i:1;s:22:"Heavy and very viscous";i:2;s:21:"Always high in sulfur";i:3;s:14:"Unable to flow";}', '', 'Ringan dan kurang kental', 'Light and less viscous', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000666', 'Kompresibilitas fluida menggambarkan...', 'Fluid compressibility describes...', 'option', 'PFC000000003', 'Soal Inisialisasi', 'a:4:{i:0;s:48:"Perubahan volume fluida akibat perubahan tekanan";i:1;s:22:"Perubahan warna fluida";i:2;s:34:"Kemampuan fluida melarutkan batuan";i:3;s:23:"Kecepatan aliran fluida";}', 'a:4:{i:0;s:51:"The change in fluid volume due to a pressure change";i:1;s:25:"The change in fluid color";i:2;s:41:"The ability of the fluid to dissolve rock";i:3;s:23:"The fluid flow velocity";}', '', 'Perubahan volume fluida akibat perubahan tekanan', 'The change in fluid volume due to a pressure change', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000667', 'Manakah yang termasuk sifat fisik fluida reservoir?', 'Which of the following are physical properties of reservoir fluids?', 'multi', 'PFC000000003', 'Soal Inisialisasi', 'a:4:{i:0;s:10:"Viskositas";i:1;s:21:"Faktor volume formasi";i:2;s:13:"Kelarutan gas";i:3;s:16:"Porositas batuan";}', 'a:4:{i:0;s:9:"Viscosity";i:1;s:23:"Formation volume factor";i:2;s:14:"Gas solubility";i:3;s:13:"Rock porosity";}', '', 'a:3:{i:0;s:10:"Viskositas";i:1;s:21:"Faktor volume formasi";i:2;s:13:"Kelarutan gas";}', 'a:3:{i:0;s:9:"Viscosity";i:1;s:23:"Formation volume factor";i:2;s:14:"Gas solubility";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
