INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000669', 'Benarkah viskositas minyak umumnya menurun ketika suhu meningkat?', 'Is it true that oil viscosity generally decreases as temperature increases?', 'yesorno', 'PFC000000003', 'Soal Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000670', 'Minyak memiliki specific gravity 0,85. Berapa API gravity-nya?', 'An oil has a specific gravity of 0.85. What is its API gravity?', 'option', 'PFC000000003', 'Final Test Advanced', 'a:4:{i:0;s:10:"34,9 °API";i:1;s:10:"15,0 °API";i:2;s:10:"85,0 °API";i:3;s:10:"45,1 °API";}', 'a:4:{i:0;s:10:"34.9 °API";i:1;s:10:"15.0 °API";i:2;s:10:"85.0 °API";i:3;s:10:"45.1 °API";}', '', '34,9 °API', '34.9 °API', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000671', 'Jika Bo = 1,3 RB/STB, maka 1000 STB minyak di permukaan setara dengan... di reservoir.', 'If Bo = 1.3 RB/STB, then 1000 STB of oil at the surface corresponds to... in the reservoir.', 'option', 'PFC000000003', 'Final Test Advanced', 'a:4:{i:0;s:6:"770 RB";i:1;s:7:"1000 RB";i:2;s:7:"1300 RB";i:3;s:8:"13000 RB";}', 'a:4:{i:0;s:6:"770 RB";i:1;s:7:"1000 RB";i:2;s:7:"1300 RB";i:3;s:8:"13000 RB";}', '', '1300 RB', '1300 RB', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000672', 'Ketika tekanan reservoir turun di bawah bubble point, gas yang keluar dari larutan menyebabkan...', 'When reservoir pressure drops below the bubble point, gas coming out of solution causes...', 'option', 'PFC000000003', 'Final Test Advanced', 'a:4:{i:0;s:42:"Bo menurun dan viskositas minyak meningkat";i:1;s:35:"Bo meningkat dan viskositas menurun";i:2;s:32:"Tidak ada perubahan sifat fluida";i:3;s:27:"Minyak menjadi lebih ringan";}', 'a:4:{i:0;s:44:"Bo to decrease and oil viscosity to increase";i:1;s:40:"Bo to increase and viscosity to decrease";i:2;s:29:"No change in fluid properties";i:3;s:25:"The oil to become lighter";}', '', 'Bo menurun dan viskositas minyak meningkat', 'Bo to decrease and oil viscosity to increase', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000673', 'Faktor kompresibilitas gas (Z) digunakan untuk...', 'The gas compressibility factor (Z) is used to...', 'option', 'PFC000000003', 'Final Test Advanced', 'a:4:{i:0;s:48:"Mengoreksi perilaku gas nyata terhadap gas ideal";i:1;s:27:"Menghitung porositas batuan";i:2;s:22:"Menentukan wettability";i:3;s:30:"Mengukur permeabilitas relatif";}', 'a:4:{i:0;s:47:"Correct real gas behavior relative to ideal gas";i:1;s:23:"Calculate rock porosity";i:2;s:21:"Determine wettability";i:3;s:29:"Measure relative permeability";}', '', 'Mengoreksi perilaku gas nyata terhadap gas ideal', 'Correct real gas behavior relative to ideal gas', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000674', 'Reservoir dikategorikan undersaturated apabila tekanan reservoir...', 'A reservoir is classified as undersaturated when the reservoir pressure is...', 'option', 'PFC000000003', 'Final Test Advanced', 'a:4:{i:0;s:30:"Lebih tinggi dari bubble point";i:1;s:30:"Lebih rendah dari bubble point";i:2;s:24:"Sama dengan bubble point";i:3;s:28:"Sama dengan tekanan atmosfer";}', 'a:4:{i:0;s:28:"Higher than the bubble point";i:1;s:27:"Lower than the bubble point";i:2;s:25:"Equal to the bubble point";i:3;s:29:"Equal to atmospheric pressure";}', '', 'Lebih tinggi dari bubble point', 'Higher than the bubble point', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000675', 'Retrograde condensation terjadi pada reservoir gas-kondensat ketika tekanan...', 'Retrograde condensation occurs in a gas-condensate reservoir when the pressure...', 'option', 'PFC000000003', 'Final Test Advanced', 'a:4:{i:0;s:50:"Turun di bawah dew point sehingga cairan mengembun";i:1;s:46:"Naik di atas dew point sehingga cairan menguap";i:2;s:32:"Tetap konstan sepanjang produksi";i:3;s:30:"Sama dengan tekanan kritis air";}', 'a:4:{i:0;s:45:"Falls below the dew point so liquid condenses";i:1;s:45:"Rises above the dew point so liquid vaporizes";i:2;s:38:"Remains constant throughout production";i:3;s:37:"Equals the critical pressure of water";}', '', 'Turun di bawah dew point sehingga cairan mengembun', 'Falls below the dew point so liquid condenses', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000676', 'Gradien tekanan fluida di reservoir digunakan untuk menentukan...', 'Fluid pressure gradients in a reservoir are used to determine...', 'option', 'PFC000000003', 'Final Test Advanced', 'a:4:{i:0;s:43:"Kontak fluida (GOC/WOC) dan densitas fluida";i:1;s:16:"Porositas batuan";i:2;s:13:"Kadar lempung";i:3;s:20:"Kekuatan semen sumur";}', 'a:4:{i:0;s:44:"Fluid contacts (GOC/WOC) and fluid densities";i:1;s:13:"Rock porosity";i:2;s:12:"Clay content";i:3;s:20:"Well cement strength";}', '', 'Kontak fluida (GOC/WOC) dan densitas fluida', 'Fluid contacts (GOC/WOC) and fluid densities', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000677', 'Minyak berat (heavy oil) umumnya memiliki...', 'Heavy oil generally has...', 'option', 'PFC000000003', 'Final Test Advanced', 'a:4:{i:0;s:32:"API rendah dan viskositas tinggi";i:1;s:32:"API tinggi dan viskositas rendah";i:2;s:32:"API rendah dan viskositas rendah";i:3;s:32:"API tinggi dan viskositas tinggi";}', 'a:4:{i:0;s:26:"Low API and high viscosity";i:1;s:26:"High API and low viscosity";i:2;s:25:"Low API and low viscosity";i:3;s:27:"High API and high viscosity";}', '', 'API rendah dan viskositas tinggi', 'Low API and high viscosity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000678', 'Kelarutan gas (Rs) yang tinggi pada minyak umumnya menyebabkan...', 'High gas solubility (Rs) in oil generally causes...', 'option', 'PFC000000003', 'Final Test Advanced', 'a:4:{i:0;s:35:"Bo meningkat dan viskositas menurun";i:1;s:35:"Bo menurun dan viskositas meningkat";i:2;s:25:"Tidak berpengaruh pada Bo";i:3;s:26:"Minyak menjadi lebih berat";}', 'a:4:{i:0;s:40:"Bo to increase and viscosity to decrease";i:1;s:40:"Bo to decrease and viscosity to increase";i:2;s:15:"No effect on Bo";i:3;s:25:"The oil to become heavier";}', '', 'Bo meningkat dan viskositas menurun', 'Bo to increase and viscosity to decrease', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
