INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000699', 'Benarkah nilai gamma ray yang tinggi menandakan zona reservoir yang bersih?', 'Is it true that a high gamma ray value indicates a clean reservoir zone?', 'yesorno', 'PFC000000004', 'Soal Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000700', 'Diketahui RHOB 2,20 g/cc, densitas matriks 2,65 g/cc, densitas fluida 1,00 g/cc. Berapa porositas densitas (φD)?', 'Given RHOB 2.20 g/cc, matrix density 2.65 g/cc, and fluid density 1.00 g/cc. What is the density porosity (φD)?', 'option', 'PFC000000004', 'Final Test Advanced', 'a:4:{i:0;s:5:"18,2%";i:1;s:5:"27,3%";i:2;s:5:"33,3%";i:3;s:5:"45,0%";}', 'a:4:{i:0;s:5:"18.2%";i:1;s:5:"27.3%";i:2;s:5:"33.3%";i:3;s:5:"45.0%";}', '', '27,3%', '27.3%', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000701', 'Efek crossover antara kurva neutron dan density yang saling menjauh biasanya menandakan...', 'The crossover effect between diverging neutron and density curves usually indicates...', 'option', 'PFC000000004', 'Final Test Advanced', 'a:4:{i:0;s:23:"Adanya gas (gas effect)";i:1;s:15:"Adanya air asin";i:2;s:13:"Batuan serpih";i:3;s:20:"Kerusakan lubang bor";}', 'a:4:{i:0;s:32:"The presence of gas (gas effect)";i:1;s:21:"The presence of brine";i:2;s:10:"Shale rock";i:3;s:15:"Borehole damage";}', '', 'Adanya gas (gas effect)', 'The presence of gas (gas effect)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000702', 'Indeks gamma ray (IGR) dihitung dengan persamaan...', 'The gamma ray index (IGR) is calculated by the equation...', 'option', 'PFC000000004', 'Final Test Advanced', 'a:4:{i:0;s:30:"(GR - GRmin) / (GRmax - GRmin)";i:1;s:17:"(GRmax - GR) / GR";i:2;s:20:"(GRmin + GR) / GRmax";i:3;s:17:"GR / GRmax × 100";}', 'a:4:{i:0;s:30:"(GR - GRmin) / (GRmax - GRmin)";i:1;s:17:"(GRmax - GR) / GR";i:2;s:20:"(GRmin + GR) / GRmax";i:3;s:17:"GR / GRmax × 100";}', '', '(GR - GRmin) / (GRmax - GRmin)', '(GR - GRmin) / (GRmax - GRmin)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
