INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000722', 'Cutoff dalam evaluasi formasi digunakan untuk...', 'Cutoffs in formation evaluation are used to...', 'option', 'PFC000000005', 'Soal Inisialisasi', 'a:4:{i:0;s:51:"Menentukan batas nilai agar zona dianggap produktif";i:1;s:20:"Menentukan warna log";i:2;s:26:"Menghitung kedalaman sumur";i:3;s:18:"Mengukur laju alir";}', 'a:4:{i:0;s:66:"Define the value thresholds for a zone to be considered productive";i:1;s:20:"Determine log colors";i:2;s:20:"Calculate well depth";i:3;s:17:"Measure flow rate";}', '', 'Menentukan batas nilai agar zona dianggap produktif', 'Define the value thresholds for a zone to be considered productive', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000723', 'Net pay adalah bagian reservoir yang...', 'Net pay is the part of the reservoir that...', 'option', 'PFC000000005', 'Soal Inisialisasi', 'a:4:{i:0;s:52:"Memenuhi cutoff dan mengandung hidrokarbon produktif";i:1;s:21:"Selalu mengandung air";i:2;s:22:"Memiliki porositas nol";i:3;s:30:"Berada di atas permukaan tanah";}', 'a:4:{i:0;s:54:"Meets the cutoffs and contains productive hydrocarbons";i:1;s:21:"Always contains water";i:2;s:17:"Has zero porosity";i:3;s:27:"Is above the ground surface";}', '', 'Memenuhi cutoff dan mengandung hidrokarbon produktif', 'Meets the cutoffs and contains productive hydrocarbons', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
