INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000739', 'Jika Sw = 60% dan Sxo = 30%, maka zona tersebut...', 'If Sw = 60% and Sxo = 30%, then the zone...', 'option', 'PFC000000005', 'Final Test Advanced', 'a:4:{i:0;s:48:"Mengandung hidrokarbon mobile yang cukup menarik";i:1;s:28:"Tidak mengandung hidrokarbon";i:2;s:21:"Seluruhnya terisi air";i:3;s:21:"Merupakan zona serpih";}', 'a:4:{i:0;s:41:"Contains movable hydrocarbons of interest";i:1;s:24:"Contains no hydrocarbons";i:2;s:24:"Is entirely water-filled";i:3;s:15:"Is a shale zone";}', '', 'Mengandung hidrokarbon mobile yang cukup menarik', 'Contains movable hydrocarbons of interest', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000740', 'Volume hidrokarbon per satuan volume batuan dihitung dengan...', 'Hydrocarbon volume per unit rock volume is calculated as...', 'option', 'PFC000000005', 'Final Test Advanced', 'a:4:{i:0;s:14:"φ × (1 - Sw)";i:1;s:8:"φ × Sw";i:2;s:14:"(1 - φ) × Sw";i:3;s:7:"φ + Sw";}', 'a:4:{i:0;s:14:"φ × (1 - Sw)";i:1;s:8:"φ × Sw";i:2;s:14:"(1 - φ) × Sw";i:3;s:7:"φ + Sw";}', '', 'φ × (1 - Sw)', 'φ × (1 - Sw)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000741', 'Pada batupasir lempungan, penggunaan persamaan Archie langsung tanpa koreksi lempung umumnya...', 'In shaly sandstone, using Archie''s equation directly without clay correction generally...', 'option', 'PFC000000005', 'Final Test Advanced', 'a:4:{i:0;s:35:"Menghasilkan Sw yang terlalu tinggi";i:1;s:35:"Menghasilkan Sw yang terlalu rendah";i:2;s:17:"Tidak berpengaruh";i:3;s:30:"Menghasilkan porositas negatif";}', 'a:4:{i:0;s:28:"Produces Sw that is too high";i:1;s:27:"Produces Sw that is too low";i:2;s:13:"Has no effect";i:3;s:26:"Produces negative porosity";}', '', 'Menghasilkan Sw yang terlalu tinggi', 'Produces Sw that is too high', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000742', 'Manakah yang termasuk cutoff petrofisika dalam penentuan net pay?', 'Which of the following are petrophysical cutoffs in net pay determination?', 'multi', 'PFC000000005', 'Final Test Advanced', 'a:4:{i:0;s:26:"Cutoff volume serpih (Vsh)";i:1;s:16:"Cutoff porositas";i:2;s:19:"Cutoff saturasi air";i:3;s:19:"Cutoff harga minyak";}', 'a:4:{i:0;s:25:"Shale volume cutoff (Vsh)";i:1;s:15:"Porosity cutoff";i:2;s:23:"Water saturation cutoff";i:3;s:16:"Oil price cutoff";}', '', 'a:3:{i:0;s:26:"Cutoff volume serpih (Vsh)";i:1;s:16:"Cutoff porositas";i:2;s:19:"Cutoff saturasi air";}', 'a:3:{i:0;s:25:"Shale volume cutoff (Vsh)";i:1;s:15:"Porosity cutoff";i:2;s:23:"Water saturation cutoff";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000743', 'Manakah penyebab kesalahan dalam perhitungan saturasi air?', 'Which are causes of error in water saturation calculation?', 'multi', 'PFC000000005', 'Final Test Advanced', 'a:4:{i:0;s:25:"Nilai Rw yang tidak tepat";i:1;s:28:"Parameter m dan n yang salah";i:2;s:34:"Invasi lumpur yang tidak dikoreksi";i:3;s:23:"Warna core yang berbeda";}', 'a:4:{i:0;s:18:"Incorrect Rw value";i:1;s:24:"Wrong m and n parameters";i:2;s:24:"Uncorrected mud invasion";i:3;s:20:"Different core color";}', '', 'a:3:{i:0;s:25:"Nilai Rw yang tidak tepat";i:1;s:28:"Parameter m dan n yang salah";i:2;s:34:"Invasi lumpur yang tidak dikoreksi";}', 'a:3:{i:0;s:18:"Incorrect Rw value";i:1;s:24:"Wrong m and n parameters";i:2;s:24:"Uncorrected mud invasion";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000744', 'Manakah informasi yang dapat diperoleh dari analisis crossplot neutron-density?', 'Which information can be obtained from neutron-density crossplot analysis?', 'multi', 'PFC000000005', 'Final Test Advanced', 'a:4:{i:0;s:22:"Jenis litologi dominan";i:1;s:13:"Kehadiran gas";i:2;s:20:"Porositas terkoreksi";i:3;s:21:"Kedalaman total sumur";}', 'a:4:{i:0;s:23:"Dominant lithology type";i:1;s:15:"Presence of gas";i:2;s:18:"Corrected porosity";i:3;s:16:"Total well depth";}', '', 'a:3:{i:0;s:22:"Jenis litologi dominan";i:1;s:13:"Kehadiran gas";i:2;s:20:"Porositas terkoreksi";}', 'a:3:{i:0;s:23:"Dominant lithology type";i:1;s:15:"Presence of gas";i:2;s:18:"Corrected porosity";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000745', 'Manakah pernyataan yang benar tentang net pay?', 'Which statements about net pay are correct?', 'multi', 'PFC000000005', 'Final Test Advanced', 'a:4:{i:0;s:36:"Ditentukan setelah cutoff diterapkan";i:1;s:51:"Selalu lebih kecil atau sama dengan gross thickness";i:2;s:43:"Mempengaruhi perhitungan volume hidrokarbon";i:3;s:35:"Sama dengan ketebalan total formasi";}', 'a:4:{i:0;s:42:"It is determined after cutoffs are applied";i:1;s:50:"It is always less than or equal to gross thickness";i:2;s:45:"It affects the hydrocarbon volume calculation";i:3;s:39:"It equals the total formation thickness";}', '', 'a:3:{i:0;s:36:"Ditentukan setelah cutoff diterapkan";i:1;s:51:"Selalu lebih kecil atau sama dengan gross thickness";i:2;s:43:"Mempengaruhi perhitungan volume hidrokarbon";}', 'a:3:{i:0;s:42:"It is determined after cutoffs are applied";i:1;s:50:"It is always less than or equal to gross thickness";i:2;s:45:"It affects the hydrocarbon volume calculation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000746', 'Urutkan perhitungan dari data log sampai volume hidrokarbon.', 'Arrange the calculation steps from log data to hydrocarbon volume.', 'drag', 'PFC000000005', 'Final Test Advanced', 'a:5:{i:0;s:18:"Vsh dari gamma ray";i:1;s:30:"Porositas dari density/neutron";i:2;s:14:"Sw dari Archie";i:3;s:13:"Tebal net pay";i:4;s:18:"Volume hidrokarbon";}', 'a:5:{i:0;s:18:"Vsh from gamma ray";i:1;s:29:"Porosity from density/neutron";i:2;s:14:"Sw from Archie";i:3;s:17:"Net pay thickness";i:4;s:18:"Hydrocarbon volume";}', '', 'a:5:{i:0;s:18:"Vsh dari gamma ray";i:1;s:30:"Porositas dari density/neutron";i:2;s:14:"Sw dari Archie";i:3;s:13:"Tebal net pay";i:4;s:18:"Volume hidrokarbon";}', 'a:5:{i:0;s:18:"Vsh from gamma ray";i:1;s:29:"Porosity from density/neutron";i:2;s:14:"Sw from Archie";i:3;s:17:"Net pay thickness";i:4;s:18:"Hydrocarbon volume";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000747', 'Urutkan nilai saturasi air (Sw) dari zona paling produktif ke zona air.', 'Arrange water saturation (Sw) values from the most productive zone to the water zone.', 'drag', 'PFC000000005', 'Final Test Advanced', 'a:4:{i:0;s:17:"Sw rendah (< 30%)";i:1;s:20:"Sw sedang (30 - 50%)";i:2;s:20:"Sw tinggi (50 - 70%)";i:3;s:20:"Sw 100% (water zone)";}', 'a:4:{i:0;s:14:"Low Sw (< 30%)";i:1;s:22:"Moderate Sw (30 - 50%)";i:2;s:18:"High Sw (50 - 70%)";i:3;s:20:"Sw 100% (water zone)";}', '', 'a:4:{i:0;s:17:"Sw rendah (< 30%)";i:1;s:20:"Sw sedang (30 - 50%)";i:2;s:20:"Sw tinggi (50 - 70%)";i:3;s:20:"Sw 100% (water zone)";}', 'a:4:{i:0;s:14:"Low Sw (< 30%)";i:1;s:22:"Moderate Sw (30 - 50%)";i:2;s:18:"High Sw (50 - 70%)";i:3;s:20:"Sw 100% (water zone)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000748', 'Benarkah zona dengan resistivitas tinggi selalu berarti zona minyak?', 'Is it true that a high-resistivity zone always means an oil zone?', 'yesorno', 'PFC000000005', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000749', 'Benarkah porositas yang dipakai pada persamaan Archie adalah porositas efektif?', 'Is it true that the porosity used in Archie''s equation is effective porosity?', 'yesorno', 'PFC000000005', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000750', 'Tekanan kapiler (Pc) adalah...', 'Capillary pressure (Pc) is...', 'option', 'PFC000000006', 'Soal Inisialisasi', 'a:4:{i:0;s:68:"Perbedaan tekanan antara fasa non-wetting dan fasa wetting pada pori";i:1;s:23:"Tekanan total reservoir";i:2;s:25:"Tekanan overburden batuan";i:3;s:25:"Selisih tekanan dua sumur";}', 'a:4:{i:0;s:76:"The pressure difference between the non-wetting and wetting phases in a pore";i:1;s:28:"The total reservoir pressure";i:2;s:28:"The rock overburden pressure";i:3;s:41:"The pressure difference between two wells";}', '', 'Perbedaan tekanan antara fasa non-wetting dan fasa wetting pada pori', 'The pressure difference between the non-wetting and wetting phases in a pore', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000751', 'Persamaan tekanan kapiler untuk pori berbentuk tabung adalah...', 'The capillary pressure equation for a cylindrical pore is...', 'option', 'PFC000000006', 'Soal Inisialisasi', 'a:4:{i:0;s:18:"Pc = 2σ cosθ / r";i:1;s:17:"Pc = σ r / cosθ";i:2;s:13:"Pc = Δρ g h";i:3;s:11:"Pc = k / μ";}', 'a:4:{i:0;s:18:"Pc = 2σ cosθ / r";i:1;s:17:"Pc = σ r / cosθ";i:2;s:13:"Pc = Δρ g h";i:3;s:11:"Pc = k / μ";}', '', 'Pc = 2σ cosθ / r', 'Pc = 2σ cosθ / r', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000752', 'Proses drainage adalah proses di mana...', 'The drainage process is the process in which...', 'option', 'PFC000000006', 'Soal Inisialisasi', 'a:4:{i:0;s:55:"Fasa non-wetting mendesak fasa wetting keluar dari pori";i:1;s:38:"Fasa wetting mendesak fasa non-wetting";i:2;s:27:"Dua fasa mengalir bersamaan";i:3;s:30:"Tidak ada fluida yang bergerak";}', 'a:4:{i:0;s:66:"The non-wetting phase displaces the wetting phase out of the pores";i:1;s:49:"The wetting phase displaces the non-wetting phase";i:2;s:25:"Both phases flow together";i:3;s:14:"No fluid moves";}', '', 'Fasa non-wetting mendesak fasa wetting keluar dari pori', 'The non-wetting phase displaces the wetting phase out of the pores', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000753', 'Entry pressure adalah tekanan kapiler minimum yang diperlukan untuk...', 'Entry pressure is the minimum capillary pressure required to...', 'option', 'PFC000000006', 'Soal Inisialisasi', 'a:4:{i:0;s:50:"Memasukkan fasa non-wetting ke dalam pori terbesar";i:1;s:39:"Mengeluarkan seluruh fluida dari batuan";i:2;s:20:"Menghancurkan batuan";i:3;s:24:"Mengubah porositas total";}', 'a:4:{i:0;s:49:"Force the non-wetting phase into the largest pore";i:1;s:30:"Remove all fluid from the rock";i:2;s:14:"Crush the rock";i:3;s:21:"Change total porosity";}', '', 'Memasukkan fasa non-wetting ke dalam pori terbesar', 'Force the non-wetting phase into the largest pore', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000754', 'Permeabilitas relatif (kr) didefinisikan sebagai perbandingan antara...', 'Relative permeability (kr) is defined as the ratio between...', 'option', 'PFC000000006', 'Soal Inisialisasi', 'a:4:{i:0;s:47:"Permeabilitas efektif dan permeabilitas absolut";i:1;s:27:"Permeabilitas dan porositas";i:2;s:37:"Tekanan kapiler dan tekanan reservoir";i:3;s:23:"Viskositas dan densitas";}', 'a:4:{i:0;s:48:"Effective permeability and absolute permeability";i:1;s:25:"Permeability and porosity";i:2;s:41:"Capillary pressure and reservoir pressure";i:3;s:21:"Viscosity and density";}', '', 'Permeabilitas efektif dan permeabilitas absolut', 'Effective permeability and absolute permeability', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000755', 'Saturasi air ireduktibel (Swir) adalah saturasi air yang...', 'Irreducible water saturation (Swir) is the water saturation that...', 'option', 'PFC000000006', 'Soal Inisialisasi', 'a:4:{i:0;s:52:"Tidak dapat dikurangi lagi dengan cara mekanis biasa";i:1;s:20:"Selalu bernilai 100%";i:2;s:27:"Sama dengan saturasi minyak";i:3;s:24:"Terjadi pada tekanan nol";}', 'a:4:{i:0;s:54:"Cannot be reduced further by ordinary mechanical means";i:1;s:14:"Is always 100%";i:2;s:21:"Equals oil saturation";i:3;s:23:"Occurs at zero pressure";}', '', 'Tidak dapat dikurangi lagi dengan cara mekanis biasa', 'Cannot be reduced further by ordinary mechanical means', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000756', 'Saturasi minyak sisa (Sor) adalah...', 'Residual oil saturation (Sor) is...', 'option', 'PFC000000006', 'Soal Inisialisasi', 'a:4:{i:0;s:81:"Minyak yang tertinggal dan tidak dapat diproduksi lagi dengan metode konvensional";i:1;s:26:"Minyak yang baru terbentuk";i:2;s:32:"Minyak yang masih mengalir bebas";i:3;s:28:"Saturasi minyak di permukaan";}', 'a:4:{i:0;s:63:"Oil left behind that cannot be produced by conventional methods";i:1;s:16:"Newly formed oil";i:2;s:27:"Oil that still flows freely";i:3;s:29:"Oil saturation at the surface";}', '', 'Minyak yang tertinggal dan tidak dapat diproduksi lagi dengan metode konvensional', 'Oil left behind that cannot be produced by conventional methods', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000757', 'Faktor apa saja yang memengaruhi tekanan kapiler?', 'Which factors affect capillary pressure?', 'multi', 'PFC000000006', 'Soal Inisialisasi', 'a:4:{i:0;s:23:"Tegangan antarmuka (σ)";i:1;s:26:"Sudut kontak (wettability)";i:2;s:15:"Ukuran pori (r)";i:3;s:12:"Warna batuan";}', 'a:4:{i:0;s:24:"Interfacial tension (σ)";i:1;s:27:"Contact angle (wettability)";i:2;s:13:"Pore size (r)";i:3;s:10:"Rock color";}', '', 'a:3:{i:0;s:23:"Tegangan antarmuka (σ)";i:1;s:26:"Sudut kontak (wettability)";i:2;s:15:"Ukuran pori (r)";}', 'a:3:{i:0;s:24:"Interfacial tension (σ)";i:1;s:27:"Contact angle (wettability)";i:2;s:13:"Pore size (r)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000758', 'Urutkan proses dari kondisi batuan jenuh air sampai terbentuk saturasi air ireduktibel.', 'Arrange the process from a water-saturated rock to the formation of irreducible water saturation.', 'drag', 'PFC000000006', 'Soal Inisialisasi', 'a:4:{i:0;s:22:"Batuan 100% terisi air";i:1;s:39:"Fasa non-wetting mulai masuk (drainage)";i:2;s:25:"Tekanan kapiler meningkat";i:3;s:32:"Air terdesak hingga tersisa Swir";}', 'a:4:{i:0;s:22:"Rock 100% water-filled";i:1;s:44:"Non-wetting phase begins to enter (drainage)";i:2;s:28:"Capillary pressure increases";i:3;s:37:"Water is displaced until Swir remains";}', '', 'a:4:{i:0;s:22:"Batuan 100% terisi air";i:1;s:39:"Fasa non-wetting mulai masuk (drainage)";i:2;s:25:"Tekanan kapiler meningkat";i:3;s:32:"Air terdesak hingga tersisa Swir";}', 'a:4:{i:0;s:22:"Rock 100% water-filled";i:1;s:44:"Non-wetting phase begins to enter (drainage)";i:2;s:28:"Capillary pressure increases";i:3;s:37:"Water is displaced until Swir remains";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000759', 'Benarkah kurva relative permeability bergantung pada wettability batuan?', 'Is it true that the relative permeability curve depends on rock wettability?', 'yesorno', 'PFC000000006', 'Soal Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000760', 'Diketahui σ = 0,03 N/m, θ = 30°, dan r = 1 µm. Berapa tekanan kapiler pada pori tersebut?', 'Given σ = 0.03 N/m, θ = 30°, and r = 1 µm. What is the capillary pressure in that pore?', 'option', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:9:"0,052 bar";i:1;s:8:"0,52 bar";i:2;s:7:"5,2 bar";i:3;s:6:"52 bar";}', 'a:4:{i:0;s:9:"0.052 bar";i:1;s:8:"0.52 bar";i:2;s:7:"5.2 bar";i:3;s:6:"52 bar";}', '', '0,52 bar', '0.52 bar', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000761', 'Konversi tekanan kapiler dari data laboratorium ke kondisi reservoir dilakukan dengan mengalikan rasio...', 'Converting capillary pressure from laboratory data to reservoir conditions is done by multiplying the ratio of...', 'option', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:46:"(σ cosθ) reservoir / (σ cosθ) laboratorium";i:1;s:38:"(σ r) reservoir / (σ r) laboratorium";i:2;s:35:"Porositas reservoir / porositas lab";i:3;s:37:"Viskositas reservoir / viskositas lab";}', 'a:4:{i:0;s:44:"(σ cosθ) reservoir / (σ cosθ) laboratory";i:1;s:36:"(σ r) reservoir / (σ r) laboratory";i:2;s:33:"Reservoir porosity / lab porosity";i:3;s:35:"Reservoir viscosity / lab viscosity";}', '', '(σ cosθ) reservoir / (σ cosθ) laboratorium', '(σ cosθ) reservoir / (σ cosθ) laboratory', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000762', 'Fungsi Leverett J digunakan untuk...', 'The Leverett J-function is used to...', 'option', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:43:"Menyeragamkan kurva Pc dari berbagai batuan";i:1;s:24:"Menghitung laju produksi";i:2;s:26:"Menentukan kedalaman sumur";i:3;s:25:"Menghitung viskositas gas";}', 'a:4:{i:0;s:40:"Normalize Pc curves from different rocks";i:1;s:25:"Calculate production rate";i:2;s:20:"Determine well depth";i:3;s:23:"Calculate gas viscosity";}', '', 'Menyeragamkan kurva Pc dari berbagai batuan', 'Normalize Pc curves from different rocks', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000763', 'Jika Pc = 50 kPa, selisih densitas fluida 300 kg/m³, dan g = 9,81 m/s², berapa tinggi kolom di atas free water level?', 'If Pc = 50 kPa, fluid density difference = 300 kg/m³, and g = 9.81 m/s², what is the column height above the free water level?', 'option', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:5:"1,7 m";i:1;s:4:"17 m";i:2;s:4:"50 m";i:3;s:5:"170 m";}', 'a:4:{i:0;s:5:"1.7 m";i:1;s:4:"17 m";i:2;s:4:"50 m";i:3;s:5:"170 m";}', '', '17 m', '17 m', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000764', 'Ketika saturasi air menurun dari Sw = 1, relative permeability minyak (kro) akan...', 'As water saturation decreases from Sw = 1, the relative permeability to oil (kro) will...', 'option', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:38:"Meningkat dari 0 sampai nilai maksimum";i:1;s:16:"Menurun menuju 0";i:2;s:13:"Tetap konstan";i:3;s:15:"Menjadi negatif";}', 'a:4:{i:0;s:34:"Increase from 0 to a maximum value";i:1;s:17:"Decrease toward 0";i:2;s:15:"Remain constant";i:3;s:15:"Become negative";}', '', 'Meningkat dari 0 sampai nilai maksimum', 'Increase from 0 to a maximum value', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000765', 'Hysteresis pada kurva Pc menunjukkan bahwa...', 'Hysteresis in the Pc curve shows that...', 'option', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:45:"Kurva drainage dan imbibition tidak berhimpit";i:1;s:26:"Tekanan kapiler selalu nol";i:2;s:19:"Kurva selalu linier";i:3;s:29:"Wettability tidak berpengaruh";}', 'a:4:{i:0;s:50:"The drainage and imbibition curves do not coincide";i:1;s:33:"Capillary pressure is always zero";i:2;s:26:"The curve is always linear";i:3;s:25:"Wettability has no effect";}', '', 'Kurva drainage dan imbibition tidak berhimpit', 'The drainage and imbibition curves do not coincide', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000766', 'Perubahan wettability dari water-wet menjadi oil-wet umumnya menyebabkan...', 'Changing wettability from water-wet to oil-wet generally causes...', 'option', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:43:"Kurva krw bergeser ke kanan dan kro menurun";i:1;s:44:"Kurva krw bergeser ke kiri dan kro meningkat";i:2;s:25:"Tidak ada perubahan kurva";i:3;s:16:"Swir menjadi nol";}', 'a:4:{i:0;s:44:"The krw curve shifts right and kro decreases";i:1;s:43:"The krw curve shifts left and kro increases";i:2;s:23:"No change in the curves";i:3;s:17:"Swir becomes zero";}', '', 'Kurva krw bergeser ke kanan dan kro menurun', 'The krw curve shifts right and kro decreases', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000767', 'Bilangan kapiler (capillary number) yang meningkat menunjukkan...', 'An increasing capillary number indicates...', 'option', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:63:"Gaya viskos lebih dominan sehingga saturasi minyak sisa menurun";i:1;s:26:"Gaya kapiler lebih dominan";i:2;s:41:"Tidak ada pengaruh terhadap saturasi sisa";i:3;s:19:"Porositas meningkat";}', 'a:4:{i:0;s:69:"Viscous forces are more dominant so residual oil saturation decreases";i:1;s:34:"Capillary forces are more dominant";i:2;s:32:"No effect on residual saturation";i:3;s:18:"Porosity increases";}', '', 'Gaya viskos lebih dominan sehingga saturasi minyak sisa menurun', 'Viscous forces are more dominant so residual oil saturation decreases', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000768', 'Pada kurva relative permeability, titik kro = 0 biasanya terjadi pada...', 'On the relative permeability curve, the point kro = 0 usually occurs at...', 'option', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:37:"Saturasi air tinggi mendekati 1 - Sor";i:1;s:24:"Saturasi air ireduktibel";i:2;s:16:"Saturasi air 50%";i:3;s:20:"Saturasi minyak 100%";}', 'a:4:{i:0;s:41:"High water saturation approaching 1 - Sor";i:1;s:28:"Irreducible water saturation";i:2;s:20:"50% water saturation";i:3;s:19:"100% oil saturation";}', '', 'Saturasi air tinggi mendekati 1 - Sor', 'High water saturation approaching 1 - Sor', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000769', 'Mobility ratio (M) yang lebih besar dari 1 menunjukkan...', 'A mobility ratio (M) greater than 1 indicates...', 'option', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:76:"Fluida pendesak lebih mobile daripada fluida terdesak (sweep kurang efisien)";i:1;s:20:"Sweep sangat efisien";i:2;s:16:"Tidak ada aliran";i:3;s:33:"Viskositas pendesak sangat tinggi";}', 'a:4:{i:0;s:73:"The displacing fluid is more mobile than the displaced fluid (poor sweep)";i:1;s:20:"Very efficient sweep";i:2;s:14:"No flow occurs";i:3;s:44:"The displacing fluid has very high viscosity";}', '', 'Fluida pendesak lebih mobile daripada fluida terdesak (sweep kurang efisien)', 'The displacing fluid is more mobile than the displaced fluid (poor sweep)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000770', 'Metode Purcell digunakan untuk...', 'The Purcell method is used to...', 'option', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:50:"Menghitung permeabilitas dari data tekanan kapiler";i:1;s:26:"Menghitung kedalaman sumur";i:2;s:28:"Menentukan jenis hidrokarbon";i:3;s:26:"Mengukur viskositas fluida";}', 'a:4:{i:0;s:51:"Calculate permeability from capillary pressure data";i:1;s:20:"Calculate well depth";i:2;s:26:"Determine hydrocarbon type";i:3;s:23:"Measure fluid viscosity";}', '', 'Menghitung permeabilitas dari data tekanan kapiler', 'Calculate permeability from capillary pressure data', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000771', 'Pengukuran relative permeability metode unsteady-state umumnya menggunakan...', 'The unsteady-state relative permeability measurement method generally uses...', 'option', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:80:"Displacement fluida dengan laju tertentu sambil mencatat produksi terhadap waktu";i:1;s:30:"Pengukuran statis tanpa aliran";i:2;s:23:"Pengukuran warna fluida";i:3;s:34:"Pengukuran tekanan overburden saja";}', 'a:4:{i:0;s:71:"Fluid displacement at a given rate while recording production over time";i:1;s:31:"Static measurement without flow";i:2;s:23:"Fluid color measurement";i:3;s:36:"Overburden pressure measurement only";}', '', 'Displacement fluida dengan laju tertentu sambil mencatat produksi terhadap waktu', 'Fluid displacement at a given rate while recording production over time', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000772', 'Manakah pernyataan yang benar tentang kurva tekanan kapiler?', 'Which statements about the capillary pressure curve are correct?', 'multi', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:38:"Pori kecil membutuhkan Pc lebih tinggi";i:1;s:45:"Entry pressure berkaitan dengan pori terbesar";i:2;s:29:"Kurva dipengaruhi wettability";i:3;s:43:"Pc tidak bergantung pada tegangan antarmuka";}', 'a:4:{i:0;s:29:"Small pores require higher Pc";i:1;s:45:"Entry pressure is related to the largest pore";i:2;s:36:"The curve is affected by wettability";i:3;s:41:"Pc does not depend on interfacial tension";}', '', 'a:3:{i:0;s:38:"Pori kecil membutuhkan Pc lebih tinggi";i:1;s:45:"Entry pressure berkaitan dengan pori terbesar";i:2;s:29:"Kurva dipengaruhi wettability";}', 'a:3:{i:0;s:29:"Small pores require higher Pc";i:1;s:45:"Entry pressure is related to the largest pore";i:2;s:36:"The curve is affected by wettability";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000773', 'Manakah yang memengaruhi bentuk kurva relative permeability?', 'Which factors affect the shape of the relative permeability curve?', 'multi', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:18:"Wettability batuan";i:1;s:22:"Distribusi ukuran pori";i:2;s:32:"Saturasi awal dan riwayat aliran";i:3;s:12:"Warna fluida";}', 'a:4:{i:0;s:16:"Rock wettability";i:1;s:22:"Pore size distribution";i:2;s:35:"Initial saturation and flow history";i:3;s:11:"Fluid color";}', '', 'a:3:{i:0;s:18:"Wettability batuan";i:1;s:22:"Distribusi ukuran pori";i:2;s:32:"Saturasi awal dan riwayat aliran";}', 'a:3:{i:0;s:16:"Rock wettability";i:1;s:22:"Pore size distribution";i:2;s:35:"Initial saturation and flow history";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000774', 'Manakah aplikasi data tekanan kapiler dalam industri?', 'Which are applications of capillary pressure data in the industry?', 'multi', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:48:"Menentukan zona transisi dan distribusi saturasi";i:1;s:51:"Menentukan ketinggian kolom hidrokarbon di atas FWL";i:2;s:26:"Mengestimasi permeabilitas";i:3;s:28:"Menentukan harga jual minyak";}', 'a:4:{i:0;s:59:"Determining the transition zone and saturation distribution";i:1;s:47:"Determining hydrocarbon column height above FWL";i:2;s:23:"Estimating permeability";i:3;s:33:"Determining the oil selling price";}', '', 'a:3:{i:0;s:48:"Menentukan zona transisi dan distribusi saturasi";i:1;s:51:"Menentukan ketinggian kolom hidrokarbon di atas FWL";i:2;s:26:"Mengestimasi permeabilitas";}', 'a:3:{i:0;s:59:"Determining the transition zone and saturation distribution";i:1;s:47:"Determining hydrocarbon column height above FWL";i:2;s:23:"Estimating permeability";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000775', 'Manakah pernyataan yang benar tentang saturasi sisa?', 'Which statements about residual saturation are correct?', 'multi', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:50:"Sor bergantung pada wettability dan sejarah aliran";i:1;s:36:"Swir dapat diperkirakan dari data Pc";i:2;s:38:"Sor dapat diturunkan dengan metode EOR";i:3;s:27:"Swir selalu sama dengan Sor";}', 'a:4:{i:0;s:43:"Sor depends on wettability and flow history";i:1;s:34:"Swir can be estimated from Pc data";i:2;s:33:"Sor can be reduced by EOR methods";i:3;s:27:"Swir is always equal to Sor";}', '', 'a:3:{i:0;s:50:"Sor bergantung pada wettability dan sejarah aliran";i:1;s:36:"Swir dapat diperkirakan dari data Pc";i:2;s:38:"Sor dapat diturunkan dengan metode EOR";}', 'a:3:{i:0;s:43:"Sor depends on wettability and flow history";i:1;s:34:"Swir can be estimated from Pc data";i:2;s:33:"Sor can be reduced by EOR methods";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000776', 'Urutkan tahapan pengukuran kurva tekanan kapiler di laboratorium.', 'Arrange the laboratory capillary pressure curve measurement steps.', 'drag', 'PFC000000006', 'Final Test Advanced', 'a:5:{i:0;s:21:"Persiapan sampel core";i:1;s:37:"Penjenuhan sampel dengan fasa wetting";i:2;s:50:"Pemberian tekanan bertahap dengan fasa non-wetting";i:3;s:39:"Pencatatan saturasi pada setiap tekanan";i:4;s:18:"Pembuatan kurva Pc";}', 'a:5:{i:0;s:23:"Core sample preparation";i:1;s:44:"Saturating the sample with the wetting phase";i:2;s:54:"Applying pressure in stages with the non-wetting phase";i:3;s:37:"Recording saturation at each pressure";i:4;s:21:"Plotting the Pc curve";}', '', 'a:5:{i:0;s:21:"Persiapan sampel core";i:1;s:37:"Penjenuhan sampel dengan fasa wetting";i:2;s:50:"Pemberian tekanan bertahap dengan fasa non-wetting";i:3;s:39:"Pencatatan saturasi pada setiap tekanan";i:4;s:18:"Pembuatan kurva Pc";}', 'a:5:{i:0;s:23:"Core sample preparation";i:1;s:44:"Saturating the sample with the wetting phase";i:2;s:54:"Applying pressure in stages with the non-wetting phase";i:3;s:37:"Recording saturation at each pressure";i:4;s:21:"Plotting the Pc curve";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000777', 'Urutkan nilai saturasi air dari yang tertinggi ke terendah sepanjang proses drainage.', 'Arrange water saturation values from highest to lowest during drainage.', 'drag', 'PFC000000006', 'Final Test Advanced', 'a:4:{i:0;s:16:"100% (jenuh air)";i:1;s:26:"Zona transisi (Sw menurun)";i:2;s:14:"Mendekati Swir";i:3;s:27:"Saturasi air minimum (Swir)";}', 'a:4:{i:0;s:22:"100% (water saturated)";i:1;s:31:"Transition zone (Sw decreasing)";i:2;s:16:"Approaching Swir";i:3;s:31:"Minimum water saturation (Swir)";}', '', 'a:4:{i:0;s:16:"100% (jenuh air)";i:1;s:26:"Zona transisi (Sw menurun)";i:2;s:14:"Mendekati Swir";i:3;s:27:"Saturasi air minimum (Swir)";}', 'a:4:{i:0;s:22:"100% (water saturated)";i:1;s:31:"Transition zone (Sw decreasing)";i:2;s:16:"Approaching Swir";i:3;s:31:"Minimum water saturation (Swir)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000778', 'Benarkah pada batuan oil-wet, minyak cenderung menempati pori kecil?', 'Is it true that in oil-wet rock, oil tends to occupy small pores?', 'yesorno', 'PFC000000006', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000779', 'Benarkah tekanan kapiler dapat bernilai negatif pada proses imbibition?', 'Is it true that capillary pressure can be negative during imbibition?', 'yesorno', 'PFC000000006', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000780', 'Rumus volumetrik OOIP (original oil in place) memuat faktor konversi acre-ft ke barrel sebesar...', 'The volumetric OOIP (original oil in place) formula includes the acre-ft to barrel conversion factor of...', 'option', 'PFC000000007', 'Soal Inisialisasi', 'a:4:{i:0;s:5:"7.758";i:1;s:5:"775,8";i:2;s:9:"7.758.000";i:3;s:5:"1.000";}', 'a:4:{i:0;s:5:"7,758";i:1;s:5:"775.8";i:2;s:9:"7,758,000";i:3;s:5:"1,000";}', '', '7.758', '7,758', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000781', 'Net-to-gross ratio (NTG) adalah perbandingan antara...', 'The net-to-gross ratio (NTG) is the ratio between...', 'option', 'PFC000000007', 'Soal Inisialisasi', 'a:4:{i:0;s:45:"Ketebalan net pay dan ketebalan total formasi";i:1;s:27:"Porositas dan permeabilitas";i:2;s:32:"Saturasi minyak dan saturasi air";i:3;s:37:"Volume reservoir dan volume permukaan";}', 'a:4:{i:0;s:47:"Net pay thickness and total formation thickness";i:1;s:25:"Porosity and permeability";i:2;s:35:"Oil saturation and water saturation";i:3;s:35:"Reservoir volume and surface volume";}', '', 'Ketebalan net pay dan ketebalan total formasi', 'Net pay thickness and total formation thickness', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000782', 'Recovery factor (RF) menyatakan...', 'The recovery factor (RF) expresses...', 'option', 'PFC000000007', 'Soal Inisialisasi', 'a:4:{i:0;s:47:"Perbandingan cadangan terproduksi terhadap OOIP";i:1;s:36:"Perbandingan OOIP terhadap luas area";i:2;s:35:"Perbandingan porositas dan saturasi";i:3;s:35:"Perbandingan tekanan awal dan akhir";}', 'a:4:{i:0;s:41:"The ratio of recoverable reserves to OOIP";i:1;s:33:"The ratio of OOIP to areal extent";i:2;s:35:"The ratio of porosity to saturation";i:3;s:39:"The ratio of initial and final pressure";}', '', 'Perbandingan cadangan terproduksi terhadap OOIP', 'The ratio of recoverable reserves to OOIP', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000783', 'OOIP adalah singkatan dari...', 'OOIP stands for...', 'option', 'PFC000000007', 'Soal Inisialisasi', 'a:4:{i:0;s:21:"Original Oil In Place";i:1;s:29:"Oil Output Injection Pressure";i:2;s:27:"Operating Oil Index Program";i:3;s:31:"Overburden Oil Initial Pressure";}', 'a:4:{i:0;s:21:"Original Oil In Place";i:1;s:29:"Oil Output Injection Pressure";i:2;s:27:"Operating Oil Index Program";i:3;s:31:"Overburden Oil Initial Pressure";}', '', 'Original Oil In Place', 'Original Oil In Place', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000784', 'Metode volumetrik digunakan untuk...', 'The volumetric method is used to...', 'option', 'PFC000000007', 'Soal Inisialisasi', 'a:4:{i:0;s:62:"Menghitung volume hidrokarbon dari parameter batuan dan fluida";i:1;s:29:"Mengukur laju produksi harian";i:2;s:20:"Menentukan harga gas";i:3;s:27:"Menghitung biaya pengeboran";}', 'a:4:{i:0;s:59:"Calculate hydrocarbon volume from rock and fluid parameters";i:1;s:29:"Measure daily production rate";i:2;s:20:"Determine gas prices";i:3;s:24:"Calculate drilling costs";}', '', 'Menghitung volume hidrokarbon dari parameter batuan dan fluida', 'Calculate hydrocarbon volume from rock and fluid parameters', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000785', 'Dalam estimasi cadangan probabilistik, P90 berarti...', 'In probabilistic reserves estimation, P90 means...', 'option', 'PFC000000007', 'Soal Inisialisasi', 'a:4:{i:0;s:75:"Nilai dengan probabilitas 90% volume aktual lebih besar dari nilai tersebut";i:1;s:29:"Nilai dengan probabilitas 10%";i:2;s:15:"Nilai rata-rata";i:3;s:22:"Nilai maksimum absolut";}', 'a:4:{i:0;s:62:"The value with a 90% probability that actual volume is greater";i:1;s:32:"The value with a 10% probability";i:2;s:17:"The average value";i:3;s:26:"The absolute maximum value";}', '', 'Nilai dengan probabilitas 90% volume aktual lebih besar dari nilai tersebut', 'The value with a 90% probability that actual volume is greater', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000786', 'Saturasi hidrokarbon (So) dihitung dari...', 'Hydrocarbon saturation (So) is calculated from...', 'option', 'PFC000000007', 'Soal Inisialisasi', 'a:4:{i:0;s:6:"1 - Sw";i:1;s:6:"1 + Sw";i:2;s:7:"Sw / φ";i:3;s:7:"φ / Sw";}', 'a:4:{i:0;s:6:"1 - Sw";i:1;s:6:"1 + Sw";i:2;s:7:"Sw / φ";i:3;s:7:"φ / Sw";}', '', '1 - Sw', '1 - Sw', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000787', 'Manakah parameter yang dibutuhkan dalam perhitungan volumetrik OOIP?', 'Which parameters are required in the volumetric OOIP calculation?', 'multi', 'PFC000000007', 'Soal Inisialisasi', 'a:4:{i:0;s:9:"Luas area";i:1;s:17:"Ketebalan net pay";i:2;s:29:"Porositas dan saturasi minyak";i:3;s:26:"Faktor volume formasi (Bo)";}', 'a:4:{i:0;s:12:"Areal extent";i:1;s:17:"Net pay thickness";i:2;s:27:"Porosity and oil saturation";i:3;s:28:"Formation volume factor (Bo)";}', '', 'a:4:{i:0;s:9:"Luas area";i:1;s:17:"Ketebalan net pay";i:2;s:29:"Porositas dan saturasi minyak";i:3;s:26:"Faktor volume formasi (Bo)";}', 'a:4:{i:0;s:12:"Areal extent";i:1;s:17:"Net pay thickness";i:2;s:27:"Porosity and oil saturation";i:3;s:28:"Formation volume factor (Bo)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000788', 'Urutkan alur estimasi volume hidrokarbon secara volumetrik.', 'Arrange the volumetric hydrocarbon volume estimation workflow.', 'drag', 'PFC000000007', 'Soal Inisialisasi', 'a:5:{i:0;s:35:"Menentukan batas area dan ketebalan";i:1;s:30:"Menghitung porositas rata-rata";i:2;s:31:"Menghitung saturasi hidrokarbon";i:3;s:21:"Menentukan NTG dan Bo";i:4;s:15:"Menghitung OOIP";}', 'a:5:{i:0;s:41:"Determine the area boundary and thickness";i:1;s:26:"Calculate average porosity";i:2;s:32:"Calculate hydrocarbon saturation";i:3;s:20:"Determine NTG and Bo";i:4;s:14:"Calculate OOIP";}', '', 'a:5:{i:0;s:35:"Menentukan batas area dan ketebalan";i:1;s:30:"Menghitung porositas rata-rata";i:2;s:31:"Menghitung saturasi hidrokarbon";i:3;s:21:"Menentukan NTG dan Bo";i:4;s:15:"Menghitung OOIP";}', 'a:5:{i:0;s:41:"Determine the area boundary and thickness";i:1;s:26:"Calculate average porosity";i:2;s:32:"Calculate hydrocarbon saturation";i:3;s:20:"Determine NTG and Bo";i:4;s:14:"Calculate OOIP";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000789', 'Benarkah cadangan (reserves) selalu lebih kecil atau sama dengan OOIP?', 'Is it true that reserves are always less than or equal to OOIP?', 'yesorno', 'PFC000000007', 'Soal Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000790', 'Diketahui A = 1000 acre, h = 20 ft, φ = 0,2, So = 0,7, dan Bo = 1,2 RB/STB. Berapa OOIP-nya?', 'Given A = 1000 acres, h = 20 ft, φ = 0.2, So = 0.7, and Bo = 1.2 RB/STB. What is the OOIP?', 'option', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:9:"1,8 MMSTB";i:1;s:10:"18,1 MMSTB";i:2;s:9:"181 MMSTB";i:3;s:9:"2,2 MMSTB";}', 'a:4:{i:0;s:9:"1.8 MMSTB";i:1;s:10:"18.1 MMSTB";i:2;s:9:"181 MMSTB";i:3;s:9:"2.2 MMSTB";}', '', '18,1 MMSTB', '18.1 MMSTB', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000791', 'Diketahui A = 640 acre, h = 30 ft, φ = 0,18, Sw = 0,30, dan Bg = 0,005 ft³/SCF. Berapa OGIP-nya?', 'Given A = 640 acres, h = 30 ft, φ = 0.18, Sw = 0.30, and Bg = 0.005 ft³/SCF. What is the OGIP?', 'option', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:8:"2,1 BSCF";i:1;s:9:"21,1 BSCF";i:2;s:8:"211 BSCF";i:3;s:9:"1,05 BSCF";}', 'a:4:{i:0;s:8:"2.1 BSCF";i:1;s:9:"21.1 BSCF";i:2;s:8:"211 BSCF";i:3;s:9:"1.05 BSCF";}', '', '21,1 BSCF', '21.1 BSCF', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000792', 'Recovery factor pada reservoir dengan water drive yang kuat umumnya...', 'The recovery factor in a reservoir with strong water drive is generally...', 'option', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:41:"Lebih tinggi dibanding solution gas drive";i:1;s:41:"Lebih rendah dibanding solution gas drive";i:2;s:15:"Sama dengan nol";i:3;s:33:"Tidak dipengaruhi mekanisme drive";}', 'a:4:{i:0;s:30:"Higher than solution gas drive";i:1;s:29:"Lower than solution gas drive";i:2;s:13:"Equal to zero";i:3;s:35:"Not affected by the drive mechanism";}', '', 'Lebih tinggi dibanding solution gas drive', 'Higher than solution gas drive', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000793', 'Penerapan cutoff yang terlalu ketat pada perhitungan net pay akan menyebabkan...', 'Applying cutoffs that are too strict in net pay calculation will cause...', 'option', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:40:"OOIP menjadi lebih kecil (underestimate)";i:1;s:39:"OOIP menjadi lebih besar (overestimate)";i:2;s:18:"OOIP tidak berubah";i:3;s:25:"Porositas menjadi negatif";}', 'a:4:{i:0;s:38:"OOIP to become smaller (underestimate)";i:1;s:36:"OOIP to become larger (overestimate)";i:2;s:24:"OOIP to remain unchanged";i:3;s:27:"Porosity to become negative";}', '', 'OOIP menjadi lebih kecil (underestimate)', 'OOIP to become smaller (underestimate)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000794', 'Klasifikasi cadangan 2P terdiri dari...', 'The 2P reserves classification consists of...', 'option', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:17:"Proven + Probable";i:1;s:17:"Proven + Possible";i:2;s:19:"Probable + Possible";i:3;s:11:"Proven saja";}', 'a:4:{i:0;s:17:"Proven + Probable";i:1;s:17:"Proven + Possible";i:2;s:19:"Probable + Possible";i:3;s:11:"Proven only";}', '', 'Proven + Probable', 'Proven + Probable', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000795', 'Metode Monte Carlo dalam estimasi volume digunakan untuk...', 'The Monte Carlo method in volume estimation is used to...', 'option', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:68:"Menggabungkan ketidakpastian beberapa parameter secara probabilistik";i:1;s:26:"Menghitung laju alir sumur";i:2;s:26:"Menentukan kedalaman sumur";i:3;s:26:"Mengukur viskositas minyak";}', 'a:4:{i:0;s:63:"Combine the uncertainty of several parameters probabilistically";i:1;s:24:"Calculate well flow rate";i:2;s:20:"Determine well depth";i:3;s:21:"Measure oil viscosity";}', '', 'Menggabungkan ketidakpastian beberapa parameter secara probabilistik', 'Combine the uncertainty of several parameters probabilistically', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000796', 'Perbedaan hasil antara perhitungan volumetrik dan material balance umumnya menunjukkan...', 'A difference between volumetric and material balance results generally indicates...', 'option', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:76:"Perlu evaluasi ulang data (misalnya tekanan, geologi, atau parameter batuan)";i:1;s:23:"Perhitungan pasti benar";i:2;s:36:"Reservoir tidak memiliki hidrokarbon";i:3;s:17:"Tidak ada artinya";}', 'a:4:{i:0;s:76:"A need to re-evaluate the data (e.g., pressure, geology, or rock parameters)";i:1;s:37:"The calculation is definitely correct";i:2;s:33:"The reservoir has no hydrocarbons";i:3;s:18:"Nothing meaningful";}', '', 'Perlu evaluasi ulang data (misalnya tekanan, geologi, atau parameter batuan)', 'A need to re-evaluate the data (e.g., pressure, geology, or rock parameters)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000797', 'Upscaling parameter petrofisika dari core ke skala reservoir bertujuan untuk...', 'Upscaling petrophysical parameters from core to reservoir scale aims to...', 'option', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:55:"Memperoleh nilai representatif untuk simulasi reservoir";i:1;s:23:"Menghilangkan data core";i:2;s:23:"Mengurangi jumlah sumur";i:3;s:23:"Menentukan harga minyak";}', 'a:4:{i:0;s:53:"Obtain representative values for reservoir simulation";i:1;s:19:"Eliminate core data";i:2;s:26:"Reduce the number of wells";i:3;s:20:"Determine oil prices";}', '', 'Memperoleh nilai representatif untuk simulasi reservoir', 'Obtain representative values for reservoir simulation', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000798', 'Parameter yang paling sensitif mempengaruhi hasil OOIP pada rumus volumetrik adalah...', 'The parameter that most sensitively affects the OOIP result in the volumetric formula is...', 'option', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:45:"Porositas, saturasi, ketebalan, dan luas area";i:1;s:12:"Warna batuan";i:2;s:15:"Kedalaman sumur";i:3;s:23:"Jenis lumpur pengeboran";}', 'a:4:{i:0;s:49:"Porosity, saturation, thickness, and areal extent";i:1;s:10:"Rock color";i:2;s:10:"Well depth";i:3;s:17:"Drilling mud type";}', '', 'Porositas, saturasi, ketebalan, dan luas area', 'Porosity, saturation, thickness, and areal extent', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000799', 'Saturasi air yang digunakan untuk perhitungan volumetrik sebaiknya berasal dari...', 'The water saturation used for volumetric calculation should come from...', 'option', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:62:"Data log yang dikalibrasi dengan core dan data tekanan kapiler";i:1;s:10:"Asumsi 50%";i:2;s:38:"Data dari sumur tetangga tanpa koreksi";i:3;s:12:"Warna batuan";}', 'a:4:{i:0;s:57:"Log data calibrated with core and capillary pressure data";i:1;s:16:"A 50% assumption";i:2;s:40:"Neighboring well data without correction";i:3;s:10:"Rock color";}', '', 'Data log yang dikalibrasi dengan core dan data tekanan kapiler', 'Log data calibrated with core and capillary pressure data', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000800', 'Sweep efficiency memengaruhi...', 'Sweep efficiency affects...', 'option', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:69:"Fraksi volume reservoir yang benar-benar tersapu oleh fluida pendesak";i:1;s:22:"Porositas total batuan";i:2;s:16:"Densitas matriks";i:3;s:15:"Kedalaman sumur";}', 'a:4:{i:0;s:71:"The fraction of reservoir volume actually swept by the displacing fluid";i:1;s:19:"Total rock porosity";i:2;s:14:"Matrix density";i:3;s:10:"Well depth";}', '', 'Fraksi volume reservoir yang benar-benar tersapu oleh fluida pendesak', 'The fraction of reservoir volume actually swept by the displacing fluid', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000801', 'Estimated Ultimate Recovery (EUR) adalah...', 'Estimated Ultimate Recovery (EUR) is...', 'option', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:68:"Total perkiraan produksi kumulatif sampai akhir umur sumur/reservoir";i:1;s:24:"Produksi harian saat ini";i:2;s:11:"Volume OOIP";i:3;s:28:"Jumlah sumur yang akan dibor";}', 'a:4:{i:0;s:82:"The total estimated cumulative production until the end of the well/reservoir life";i:1;s:24:"Current daily production";i:2;s:11:"OOIP volume";i:3;s:33:"The number of wells to be drilled";}', '', 'Total perkiraan produksi kumulatif sampai akhir umur sumur/reservoir', 'The total estimated cumulative production until the end of the well/reservoir life', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000802', 'Manakah penyebab perbedaan antara OOIP volumetrik dan hasil material balance?', 'Which are causes of differences between volumetric OOIP and material balance results?', 'multi', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:31:"Data tekanan yang kurang akurat";i:1;s:33:"Ketidakpastian geometri reservoir";i:2;s:41:"Parameter batuan yang tidak representatif";i:3;s:25:"Warna minyak yang berbeda";}', 'a:4:{i:0;s:24:"Inaccurate pressure data";i:1;s:28:"Uncertain reservoir geometry";i:2;s:34:"Non-representative rock parameters";i:3;s:19:"Different oil color";}', '', 'a:3:{i:0;s:31:"Data tekanan yang kurang akurat";i:1;s:33:"Ketidakpastian geometri reservoir";i:2;s:41:"Parameter batuan yang tidak representatif";}', 'a:3:{i:0;s:24:"Inaccurate pressure data";i:1;s:28:"Uncertain reservoir geometry";i:2;s:34:"Non-representative rock parameters";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000803', 'Manakah yang termasuk sumber ketidakpastian dalam estimasi cadangan?', 'Which of the following are sources of uncertainty in reserves estimation?', 'multi', 'PFC000000007', 'Final Test Advanced', 'a:4:{i:0;s:38:"Distribusi porositas dan permeabilitas";i:1;s:33:"Kontak fluida dan batas reservoir";i:2;s:26:"Kualitas data log dan core";i:3;s:21:"Jumlah pekerja di rig";}', 'a:4:{i:0;s:38:"Porosity and permeability distribution";i:1;s:39:"Fluid contacts and reservoir boundaries";i:2;s:25:"Log and core data quality";i:3;s:28:"Number of workers on the rig";}', '', 'a:3:{i:0;s:38:"Distribusi porositas dan permeabilitas";i:1;s:33:"Kontak fluida dan batas reservoir";i:2;s:26:"Kualitas data log dan core";}', 'a:3:{i:0;s:38:"Porosity and permeability distribution";i:1;s:39:"Fluid contacts and reservoir boundaries";i:2;s:25:"Log and core data quality";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
