INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000822', 'Mobility ratio M didefinisikan sebagai...', 'Mobility ratio M is defined as...', 'option', 'PFC000000008', 'Final Test Advanced', 'a:4:{i:0;s:21:"(krw/μw) / (kro/μo)";i:1;s:21:"(kro/μo) / (krw/μw)";i:2;s:22:"(μw/μo) × (kro/krw)";i:3;s:10:"μw × μo";}', 'a:4:{i:0;s:21:"(krw/μw) / (kro/μo)";i:1;s:21:"(kro/μo) / (krw/μw)";i:2;s:22:"(μw/μo) × (kro/krw)";i:3;s:10:"μw × μo";}', '', '(krw/μw) / (kro/μo)', '(krw/μw) / (kro/μo)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000823', 'Mobility ratio yang kurang dari 1 menunjukkan...', 'A mobility ratio of less than 1 indicates...', 'option', 'PFC000000008', 'Final Test Advanced', 'a:4:{i:0;s:27:"Sweep yang baik (favorable)";i:1;s:16:"Sweep yang buruk";i:2;s:16:"Tidak ada aliran";i:3;s:21:"Viskositas minyak nol";}', 'a:4:{i:0;s:22:"Good (favorable) sweep";i:1;s:10:"Poor sweep";i:2;s:7:"No flow";i:3;s:18:"Zero oil viscosity";}', '', 'Sweep yang baik (favorable)', 'Good (favorable) sweep', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000824', 'Bilangan kapiler (capillary number) ditingkatkan pada EOR untuk...', 'The capillary number is increased in EOR to...', 'option', 'PFC000000008', 'Final Test Advanced', 'a:4:{i:0;s:31:"Menurunkan saturasi minyak sisa";i:1;s:30:"Menaikkan saturasi minyak sisa";i:2;s:19:"Menaikkan porositas";i:3;s:24:"Menurunkan permeabilitas";}', 'a:4:{i:0;s:30:"Reduce residual oil saturation";i:1;s:32:"Increase residual oil saturation";i:2;s:17:"Increase porosity";i:3;s:21:"Decrease permeability";}', '', 'Menurunkan saturasi minyak sisa', 'Reduce residual oil saturation', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000825', 'Injeksi polimer pada EOR bertujuan utama untuk...', 'Polymer injection in EOR mainly aims to...', 'option', 'PFC000000008', 'Final Test Advanced', 'a:4:{i:0;s:59:"Meningkatkan viskositas air sehingga mobility ratio membaik";i:1;s:28:"Menurunkan viskositas minyak";i:2;s:28:"Menaikkan tegangan antarmuka";i:3;s:20:"Menurunkan porositas";}', 'a:4:{i:0;s:55:"Increase water viscosity so the mobility ratio improves";i:1;s:22:"Decrease oil viscosity";i:2;s:28:"Increase interfacial tension";i:3;s:17:"Decrease porosity";}', '', 'Meningkatkan viskositas air sehingga mobility ratio membaik', 'Increase water viscosity so the mobility ratio improves', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000826', 'Injeksi surfaktan pada EOR bekerja dengan cara...', 'Surfactant injection in EOR works by...', 'option', 'PFC000000008', 'Final Test Advanced', 'a:4:{i:0;s:51:"Menurunkan tegangan antarmuka antara minyak dan air";i:1;s:27:"Menaikkan viskositas minyak";i:2;s:27:"Menurunkan porositas batuan";i:3;s:27:"Menaikkan tekanan reservoir";}', 'a:4:{i:0;s:50:"Reducing interfacial tension between oil and water";i:1;s:24:"Increasing oil viscosity";i:2;s:22:"Reducing rock porosity";i:3;s:29:"Increasing reservoir pressure";}', '', 'Menurunkan tegangan antarmuka antara minyak dan air', 'Reducing interfacial tension between oil and water', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000827', 'Injeksi alkali pada EOR umumnya memanfaatkan reaksi dengan...', 'Alkali injection in EOR generally utilizes reactions with...', 'option', 'PFC000000008', 'Final Test Advanced', 'a:4:{i:0;s:60:"Asam naftenat dalam minyak untuk membentuk surfaktan in-situ";i:1;s:19:"Kuarsa dalam batuan";i:2;s:20:"Gas CO2 di reservoir";i:3;s:17:"Air formasi murni";}', 'a:4:{i:0;s:55:"Naphthenic acids in the oil to form in-situ surfactants";i:1;s:18:"Quartz in the rock";i:2;s:24:"CO2 gas in the reservoir";i:3;s:20:"Pure formation water";}', '', 'Asam naftenat dalam minyak untuk membentuk surfaktan in-situ', 'Naphthenic acids in the oil to form in-situ surfactants', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000828', 'Metode thermal EOR paling cocok untuk reservoir dengan...', 'Thermal EOR methods are most suitable for reservoirs with...', 'option', 'PFC000000008', 'Final Test Advanced', 'a:4:{i:0;s:34:"Minyak berat dan viskositas tinggi";i:1;s:35:"Minyak ringan dan viskositas rendah";i:2;s:10:"Gas kering";i:3;s:25:"Batuan tight tanpa minyak";}', 'a:4:{i:0;s:28:"Heavy oil and high viscosity";i:1;s:27:"Light oil and low viscosity";i:2;s:7:"Dry gas";i:3;s:22:"Tight rock without oil";}', '', 'Minyak berat dan viskositas tinggi', 'Heavy oil and high viscosity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
