INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000831', 'Mekanisme utama SAGD (steam assisted gravity drainage) adalah...', 'The main mechanism of SAGD (steam assisted gravity drainage) is...', 'option', 'PFC000000008', 'Final Test Advanced', 'a:4:{i:0;s:54:"Gravitasi dan panas steam menurunkan viskositas minyak";i:1;s:30:"Peningkatan tegangan antarmuka";i:2;s:23:"Penurunan permeabilitas";i:3;s:26:"Peningkatan viskositas air";}', 'a:4:{i:0;s:43:"Gravity and steam heat reduce oil viscosity";i:1;s:30:"Increasing interfacial tension";i:2;s:21:"Reducing permeability";i:3;s:26:"Increasing water viscosity";}', '', 'Gravitasi dan panas steam menurunkan viskositas minyak', 'Gravity and steam heat reduce oil viscosity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000832', 'Manakah mekanisme yang dapat meningkatkan perolehan minyak pada EOR?', 'Which mechanisms can increase oil recovery in EOR?', 'multi', 'PFC000000008', 'Final Test Advanced', 'a:4:{i:0;s:30:"Penurunan saturasi minyak sisa";i:1;s:24:"Perbaikan mobility ratio";i:2;s:27:"Peningkatan efisiensi sweep";i:3;s:34:"Peningkatan porositas total batuan";}', 'a:4:{i:0;s:36:"Reduction of residual oil saturation";i:1;s:29:"Improvement of mobility ratio";i:2;s:28:"Increase in sweep efficiency";i:3;s:31:"Increase in total rock porosity";}', '', 'a:3:{i:0;s:30:"Penurunan saturasi minyak sisa";i:1;s:24:"Perbaikan mobility ratio";i:2;s:27:"Peningkatan efisiensi sweep";}', 'a:3:{i:0;s:36:"Reduction of residual oil saturation";i:1;s:29:"Improvement of mobility ratio";i:2;s:28:"Increase in sweep efficiency";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000833', 'Manakah data yang dibutuhkan dalam screening metode EOR?', 'Which data are needed in EOR method screening?', 'multi', 'PFC000000008', 'Final Test Advanced', 'a:4:{i:0;s:33:"Viskositas dan API gravity minyak";i:1;s:28:"Kedalaman dan suhu reservoir";i:2;s:38:"Porositas, permeabilitas, dan saturasi";i:3;s:12:"Warna batuan";}', 'a:4:{i:0;s:29:"Oil viscosity and API gravity";i:1;s:31:"Reservoir depth and temperature";i:2;s:38:"Porosity, permeability, and saturation";i:3;s:10:"Rock color";}', '', 'a:3:{i:0;s:33:"Viskositas dan API gravity minyak";i:1;s:28:"Kedalaman dan suhu reservoir";i:2;s:38:"Porositas, permeabilitas, dan saturasi";}', 'a:3:{i:0;s:29:"Oil viscosity and API gravity";i:1;s:31:"Reservoir depth and temperature";i:2;s:38:"Porosity, permeability, and saturation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000834', 'Manakah pernyataan yang benar tentang chemical EOR?', 'Which statements about chemical EOR are correct?', 'multi', 'PFC000000008', 'Final Test Advanced', 'a:4:{i:0;s:35:"Polimer meningkatkan viskositas air";i:1;s:24:"Surfaktan menurunkan IFT";i:2;s:40:"Alkali dapat membentuk surfaktan in-situ";i:3;s:36:"Polimer menurunkan viskositas minyak";}', 'a:4:{i:0;s:33:"Polymer increases water viscosity";i:1;s:22:"Surfactant reduces IFT";i:2;s:35:"Alkali can form in-situ surfactants";i:3;s:29:"Polymer reduces oil viscosity";}', '', 'a:3:{i:0;s:35:"Polimer meningkatkan viskositas air";i:1;s:24:"Surfaktan menurunkan IFT";i:2;s:40:"Alkali dapat membentuk surfaktan in-situ";}', 'a:3:{i:0;s:33:"Polymer increases water viscosity";i:1;s:22:"Surfactant reduces IFT";i:2;s:35:"Alkali can form in-situ surfactants";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
