INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000836', 'Urutkan tahapan evaluasi proyek EOR dari awal.', 'Arrange the EOR project evaluation stages from the beginning.', 'drag', 'PFC000000008', 'Final Test Advanced', 'a:5:{i:0;s:16:"Screening metode";i:1;s:18:"Studi laboratorium";i:2;s:32:"Pemodelan dan simulasi reservoir";i:3;s:9:"Uji pilot";i:4;s:21:"Implementasi lapangan";}', 'a:5:{i:0;s:16:"Method screening";i:1;s:16:"Laboratory study";i:2;s:33:"Reservoir modeling and simulation";i:3;s:10:"Pilot test";i:4;s:20:"Field implementation";}', '', 'a:5:{i:0;s:16:"Screening metode";i:1;s:18:"Studi laboratorium";i:2;s:32:"Pemodelan dan simulasi reservoir";i:3;s:9:"Uji pilot";i:4;s:21:"Implementasi lapangan";}', 'a:5:{i:0;s:16:"Method screening";i:1;s:16:"Laboratory study";i:2;s:33:"Reservoir modeling and simulation";i:3;s:10:"Pilot test";i:4;s:20:"Field implementation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000837', 'Urutkan metode EOR dari yang paling cocok untuk minyak ringan ke minyak sangat berat.', 'Arrange EOR methods from most suitable for light oil to very heavy oil.', 'drag', 'PFC000000008', 'Final Test Advanced', 'a:3:{i:0;s:13:"Gas EOR (CO2)";i:1;s:32:"Chemical EOR (polimer/surfaktan)";i:2;s:19:"Thermal EOR (steam)";}', 'a:3:{i:0;s:13:"Gas EOR (CO2)";i:1;s:33:"Chemical EOR (polymer/surfactant)";i:2;s:19:"Thermal EOR (steam)";}', '', 'a:3:{i:0;s:13:"Gas EOR (CO2)";i:1;s:32:"Chemical EOR (polimer/surfaktan)";i:2;s:19:"Thermal EOR (steam)";}', 'a:3:{i:0;s:13:"Gas EOR (CO2)";i:1;s:33:"Chemical EOR (polymer/surfactant)";i:2;s:19:"Thermal EOR (steam)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000838', 'Benarkah EOR bertujuan menurunkan saturasi minyak sisa (Sor) yang tidak dapat diproduksi oleh waterflood?', 'Is it true that EOR aims to reduce the residual oil saturation (Sor) that cannot be produced by waterflooding?', 'yesorno', 'PFC000000008', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000839', 'Benarkah metode EOR yang sama selalu optimal untuk semua jenis reservoir?', 'Is it true that the same EOR method is always optimal for all reservoir types?', 'yesorno', 'PFC000000008', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000840', 'Polymer flooding dilakukan dengan cara...', 'Polymer flooding is performed by...', 'option', 'PFC000000009', 'Soal Inisialisasi', 'a:4:{i:0;s:64:"Menambahkan polimer ke air injeksi untuk meningkatkan viskositas";i:1;s:27:"Menambahkan garam ke minyak";i:2;s:20:"Memanaskan reservoir";i:3;s:22:"Menginjeksikan gas CO2";}', 'a:4:{i:0;s:59:"Adding polymer to injection water to increase its viscosity";i:1;s:22:"Adding salt to the oil";i:2;s:21:"Heating the reservoir";i:3;s:17:"Injecting CO2 gas";}', '', 'Menambahkan polimer ke air injeksi untuk meningkatkan viskositas', 'Adding polymer to injection water to increase its viscosity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000841', 'Tujuan utama polymer flooding adalah...', 'The main purpose of polymer flooding is...', 'option', 'PFC000000009', 'Soal Inisialisasi', 'a:4:{i:0;s:46:"Memperbaiki mobility ratio dan efisiensi sweep";i:1;s:20:"Menurunkan porositas";i:2;s:28:"Menaikkan tegangan antarmuka";i:3;s:26:"Menurunkan tekanan injeksi";}', 'a:4:{i:0;s:47:"Improve the mobility ratio and sweep efficiency";i:1;s:15:"Reduce porosity";i:2;s:28:"Increase interfacial tension";i:3;s:24:"Lower injection pressure";}', '', 'Memperbaiki mobility ratio dan efisiensi sweep', 'Improve the mobility ratio and sweep efficiency', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
