INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000848', 'Urutkan proses polymer flooding dari persiapan sampai produksi.', 'Arrange the polymer flooding process from preparation to production.', 'drag', 'PFC000000009', 'Soal Inisialisasi', 'a:5:{i:0;s:21:"Persiapan air injeksi";i:1;s:19:"Pencampuran polimer";i:2;s:36:"Injeksi larutan polimer ke reservoir";i:3;s:38:"Perbaikan sweep dan pendorongan minyak";i:4;s:33:"Produksi minyak di sumur produksi";}', 'a:5:{i:0;s:27:"Injection water preparation";i:1;s:14:"Polymer mixing";i:2;s:45:"Polymer solution injection into the reservoir";i:3;s:38:"Sweep improvement and oil displacement";i:4;s:35:"Oil production at the producer well";}', '', 'a:5:{i:0;s:21:"Persiapan air injeksi";i:1;s:19:"Pencampuran polimer";i:2;s:36:"Injeksi larutan polimer ke reservoir";i:3;s:38:"Perbaikan sweep dan pendorongan minyak";i:4;s:33:"Produksi minyak di sumur produksi";}', 'a:5:{i:0;s:27:"Injection water preparation";i:1;s:14:"Polymer mixing";i:2;s:45:"Polymer solution injection into the reservoir";i:3;s:38:"Sweep improvement and oil displacement";i:4;s:35:"Oil production at the producer well";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000849', 'Benarkah polymer flooding menurunkan tegangan antarmuka secara signifikan seperti surfaktan?', 'Is it true that polymer flooding significantly reduces interfacial tension like a surfactant?', 'yesorno', 'PFC000000009', 'Soal Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000850', 'Jika viskositas air dinaikkan dari 1 cp menjadi 20 cp sementara viskositas minyak 40 cp, mobility ratio air-minyak berubah dari 40 menjadi...', 'If water viscosity is increased from 1 cp to 20 cp while oil viscosity is 40 cp, the water-oil mobility ratio changes from 40 to...', 'option', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:1:"2";i:1;s:2:"20";i:2;s:2:"40";i:3;s:3:"800";}', 'a:4:{i:0;s:1:"2";i:1;s:2:"20";i:2;s:2:"40";i:3;s:3:"800";}', '', '2', '2', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000851', 'Resistance factor (RF) pada polymer flooding didefinisikan sebagai...', 'The resistance factor (RF) in polymer flooding is defined as...', 'option', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:47:"Rasio mobilitas air sebelum dan sesudah polimer";i:1;s:33:"Rasio porositas dan permeabilitas";i:2;s:27:"Rasio tekanan dan laju alir";i:3;s:31:"Rasio viskositas minyak dan gas";}', 'a:4:{i:0;s:52:"The ratio of water mobility before and after polymer";i:1;s:37:"The ratio of porosity to permeability";i:2;s:34:"The ratio of pressure to flow rate";i:3;s:34:"The ratio of oil and gas viscosity";}', '', 'Rasio mobilitas air sebelum dan sesudah polimer', 'The ratio of water mobility before and after polymer', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000852', 'Residual resistance factor (RRF) berkaitan dengan...', 'The residual resistance factor (RRF) relates to...', 'option', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:62:"Penurunan permeabilitas air yang tersisa setelah polimer lewat";i:1;s:21:"Peningkatan porositas";i:2;s:27:"Penurunan viskositas minyak";i:3;s:29:"Peningkatan tekanan reservoir";}', 'a:4:{i:0;s:66:"The remaining reduction in water permeability after polymer passes";i:1;s:18:"Increased porosity";i:2;s:21:"Reduced oil viscosity";i:3;s:28:"Increased reservoir pressure";}', '', 'Penurunan permeabilitas air yang tersisa setelah polimer lewat', 'The remaining reduction in water permeability after polymer passes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000853', 'Kurva adsorpsi polimer umumnya berbentuk...', 'The polymer adsorption curve is generally shaped...', 'option', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:43:"Langmuir (mendatar pada konsentrasi tinggi)";i:1;s:18:"Linier tanpa batas";i:2;s:20:"Eksponensial menurun";i:3;s:25:"Parabola terbuka ke bawah";}', 'a:4:{i:0;s:45:"Langmuir (leveling off at high concentration)";i:1;s:16:"Unbounded linear";i:2;s:24:"Exponentially decreasing";i:3;s:25:"Downward-opening parabola";}', '', 'Langmuir (mendatar pada konsentrasi tinggi)', 'Langmuir (leveling off at high concentration)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000854', 'Inaccessible pore volume (IPV) menyebabkan...', 'Inaccessible pore volume (IPV) causes...', 'option', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:55:"Polimer bergerak lebih cepat dari air pada awal injeksi";i:1;s:40:"Polimer tidak dapat mengalir sama sekali";i:2;s:34:"Viskositas polimer meningkat tajam";i:3;s:20:"Adsorpsi menjadi nol";}', 'a:4:{i:0;s:59:"Polymer to move faster than water at the start of injection";i:1;s:35:"Polymer to be unable to flow at all";i:2;s:37:"Polymer viscosity to increase sharply";i:3;s:25:"Adsorption to become zero";}', '', 'Polimer bergerak lebih cepat dari air pada awal injeksi', 'Polymer to move faster than water at the start of injection', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000855', 'Larutan polimer umumnya bersifat...', 'Polymer solutions are generally...', 'option', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:30:"Non-Newtonian (shear thinning)";i:1;s:18:"Newtonian sempurna";i:2;s:18:"Bersifat gas ideal";i:3;s:20:"Tidak dapat mengalir";}', 'a:4:{i:0;s:30:"Non-Newtonian (shear thinning)";i:1;s:19:"Perfectly Newtonian";i:2;s:18:"Ideal gas behavior";i:3;s:14:"Unable to flow";}', '', 'Non-Newtonian (shear thinning)', 'Non-Newtonian (shear thinning)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000856', 'Untuk reservoir bersalinitas tinggi dan bertemperatur tinggi, polimer yang lebih sesuai adalah...', 'For high-salinity and high-temperature reservoirs, the more suitable polymer is...', 'option', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:75:"Polimer tahan salinitas/suhu (misalnya terpolimer atau biopolimer tertentu)";i:1;s:29:"HPAM standar tanpa modifikasi";i:2;s:42:"Polimer dengan berat molekul sangat rendah";i:3;s:27:"Bukan polimer, tetapi garam";}', 'a:4:{i:0;s:82:"A salinity/temperature-resistant polymer (e.g., terpolymer or certain biopolymers)";i:1;s:24:"Standard unmodified HPAM";i:2;s:35:"A very low molecular weight polymer";i:3;s:23:"Not a polymer, but salt";}', '', 'Polimer tahan salinitas/suhu (misalnya terpolimer atau biopolimer tertentu)', 'A salinity/temperature-resistant polymer (e.g., terpolymer or certain biopolymers)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000857', 'Laju injeksi polimer yang terlalu tinggi berisiko...', 'A polymer injection rate that is too high risks...', 'option', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:51:"Terbentuknya rekah (fracturing) dan degradasi shear";i:1;s:33:"Peningkatan adsorpsi hingga jenuh";i:2;s:27:"Penurunan viskositas minyak";i:3;s:19:"Porositas meningkat";}', 'a:4:{i:0;s:32:"Fracturing and shear degradation";i:1;s:35:"Adsorption increasing to saturation";i:2;s:21:"Reduced oil viscosity";i:3;s:19:"Porosity increasing";}', '', 'Terbentuknya rekah (fracturing) dan degradasi shear', 'Fracturing and shear degradation', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000858', 'Konsentrasi polimer yang dinaikkan umumnya menyebabkan...', 'Increasing polymer concentration generally causes...', 'option', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:28:"Viskositas larutan meningkat";i:1;s:26:"Viskositas larutan menurun";i:2;s:20:"Adsorpsi menjadi nol";i:3;s:30:"Permeabilitas batuan meningkat";}', 'a:4:{i:0;s:30:"Solution viscosity to increase";i:1;s:30:"Solution viscosity to decrease";i:2;s:25:"Adsorption to become zero";i:3;s:29:"Rock permeability to increase";}', '', 'Viskositas larutan meningkat', 'Solution viscosity to increase', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000859', 'Slug polimer biasanya diikuti oleh...', 'The polymer slug is usually followed by...', 'option', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:36:"Air chase water untuk mendorong slug";i:1;s:7:"Gas CO2";i:2;s:15:"Surfaktan pekat";i:3;s:5:"Semen";}', 'a:4:{i:0;s:28:"Chase water to push the slug";i:1;s:7:"CO2 gas";i:2;s:23:"Concentrated surfactant";i:3;s:6:"Cement";}', '', 'Air chase water untuk mendorong slug', 'Chase water to push the slug', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000860', 'Kehilangan polimer akibat adsorpsi paling besar pada batuan dengan...', 'Polymer loss due to adsorption is greatest in rock with...', 'option', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:47:"Luas permukaan spesifik tinggi (banyak lempung)";i:1;s:27:"Permeabilitas sangat tinggi";i:2;s:23:"Porositas sangat rendah";i:3;s:22:"Kandungan kuarsa murni";}', 'a:4:{i:0;s:46:"High specific surface area (high clay content)";i:1;s:22:"Very high permeability";i:2;s:17:"Very low porosity";i:3;s:19:"Pure quartz content";}', '', 'Luas permukaan spesifik tinggi (banyak lempung)', 'High specific surface area (high clay content)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000861', 'Keberhasilan polymer flooding paling sensitif terhadap...', 'The success of polymer flooding is most sensitive to...', 'option', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:51:"Kualitas air, salinitas, dan shear saat pencampuran";i:1;s:12:"Warna minyak";i:2;s:18:"Jenis casing sumur";i:3;s:15:"Kedalaman sumur";}', 'a:4:{i:0;s:48:"Water quality, salinity, and shear during mixing";i:1;s:9:"Oil color";i:2;s:16:"Well casing type";i:3;s:10:"Well depth";}', '', 'Kualitas air, salinitas, dan shear saat pencampuran', 'Water quality, salinity, and shear during mixing', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000862', 'Manakah mekanisme penurunan kinerja polimer di reservoir?', 'Which are mechanisms of polymer performance degradation in the reservoir?', 'multi', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:30:"Adsorpsi pada permukaan batuan";i:1;s:15:"Degradasi shear";i:2;s:23:"Degradasi kimia/thermal";i:3;s:26:"Peningkatan viskositas air";}', 'a:4:{i:0;s:27:"Adsorption on rock surfaces";i:1;s:17:"Shear degradation";i:2;s:28:"Chemical/thermal degradation";i:3;s:25:"Increased water viscosity";}', '', 'a:3:{i:0;s:30:"Adsorpsi pada permukaan batuan";i:1;s:15:"Degradasi shear";i:2;s:23:"Degradasi kimia/thermal";}', 'a:3:{i:0;s:27:"Adsorption on rock surfaces";i:1;s:17:"Shear degradation";i:2;s:28:"Chemical/thermal degradation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000863', 'Manakah kelebihan polymer flooding?', 'Which are advantages of polymer flooding?', 'multi', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:46:"Teknologi relatif matang dan banyak diterapkan";i:1;s:33:"Dapat memperbaiki efisiensi sweep";i:2;s:43:"Cocok untuk minyak dengan viskositas sedang";i:3;s:35:"Dapat menurunkan IFT secara drastis";}', 'a:4:{i:0;s:57:"Relatively mature technology with many field applications";i:1;s:28:"Can improve sweep efficiency";i:2;s:33:"Suitable for medium-viscosity oil";i:3;s:26:"Can drastically reduce IFT";}', '', 'a:3:{i:0;s:46:"Teknologi relatif matang dan banyak diterapkan";i:1;s:33:"Dapat memperbaiki efisiensi sweep";i:2;s:43:"Cocok untuk minyak dengan viskositas sedang";}', 'a:3:{i:0;s:57:"Relatively mature technology with many field applications";i:1;s:28:"Can improve sweep efficiency";i:2;s:33:"Suitable for medium-viscosity oil";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000864', 'Manakah parameter yang perlu diuji di laboratorium sebelum polymer flooding?', 'Which parameters must be tested in the laboratory before polymer flooding?', 'multi', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:33:"Viskositas larutan vs konsentrasi";i:1;s:20:"Adsorpsi dan retensi";i:2;s:32:"Stabilitas thermal dan salinitas";i:3;s:18:"Harga minyak dunia";}', 'a:4:{i:0;s:35:"Solution viscosity vs concentration";i:1;s:24:"Adsorption and retention";i:2;s:30:"Thermal and salinity stability";i:3;s:15:"World oil price";}', '', 'a:3:{i:0;s:33:"Viskositas larutan vs konsentrasi";i:1;s:20:"Adsorpsi dan retensi";i:2;s:32:"Stabilitas thermal dan salinitas";}', 'a:3:{i:0;s:35:"Solution viscosity vs concentration";i:1;s:24:"Adsorption and retention";i:2;s:30:"Thermal and salinity stability";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000865', 'Manakah pernyataan yang benar tentang mobility ratio pada polymer flooding?', 'Which statements about mobility ratio in polymer flooding are correct?', 'multi', 'PFC000000009', 'Final Test Advanced', 'a:4:{i:0;s:33:"M < 1 menunjukkan sweep yang baik";i:1;s:39:"Peningkatan viskositas air menurunkan M";i:2;s:35:"M dipengaruhi relative permeability";i:3;s:34:"M tidak bergantung pada viskositas";}', 'a:4:{i:0;s:26:"M < 1 indicates good sweep";i:1;s:35:"Increasing water viscosity lowers M";i:2;s:38:"M is affected by relative permeability";i:3;s:30:"M does not depend on viscosity";}', '', 'a:3:{i:0;s:33:"M < 1 menunjukkan sweep yang baik";i:1;s:39:"Peningkatan viskositas air menurunkan M";i:2;s:35:"M dipengaruhi relative permeability";}', 'a:3:{i:0;s:26:"M < 1 indicates good sweep";i:1;s:35:"Increasing water viscosity lowers M";i:2;s:38:"M is affected by relative permeability";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000866', 'Urutkan tahapan uji polymer dari skala laboratorium ke lapangan.', 'Arrange the polymer testing stages from laboratory to field scale.', 'drag', 'PFC000000009', 'Final Test Advanced', 'a:5:{i:0;s:20:"Uji rheologi larutan";i:1;s:27:"Uji adsorpsi dan core flood";i:2;s:18:"Simulasi reservoir";i:3;s:23:"Uji pilot sumur tunggal";i:4;s:21:"Ekspansi pola injeksi";}', 'a:5:{i:0;s:22:"Solution rheology test";i:1;s:30:"Adsorption and core flood test";i:2;s:20:"Reservoir simulation";i:3;s:22:"Single-well pilot test";i:4;s:27:"Injection pattern expansion";}', '', 'a:5:{i:0;s:20:"Uji rheologi larutan";i:1;s:27:"Uji adsorpsi dan core flood";i:2;s:18:"Simulasi reservoir";i:3;s:23:"Uji pilot sumur tunggal";i:4;s:21:"Ekspansi pola injeksi";}', 'a:5:{i:0;s:22:"Solution rheology test";i:1;s:30:"Adsorption and core flood test";i:2;s:20:"Reservoir simulation";i:3;s:22:"Single-well pilot test";i:4;s:27:"Injection pattern expansion";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000867', 'Urutkan langkah pencampuran polimer di permukaan.', 'Arrange the surface polymer mixing steps.', 'drag', 'PFC000000009', 'Final Test Advanced', 'a:5:{i:0;s:29:"Penyaringan dan penyiapan air";i:1;s:24:"Penambahan bubuk polimer";i:2;s:22:"Pengadukan dan hidrasi";i:3;s:33:"Pengenceran ke konsentrasi target";i:4;s:27:"Penyimpanan sebelum injeksi";}', 'a:5:{i:0;s:32:"Water filtration and preparation";i:1;s:23:"Polymer powder addition";i:2;s:20:"Mixing and hydration";i:3;s:32:"Dilution to target concentration";i:4;s:24:"Storage before injection";}', '', 'a:5:{i:0;s:29:"Penyaringan dan penyiapan air";i:1;s:24:"Penambahan bubuk polimer";i:2;s:22:"Pengadukan dan hidrasi";i:3;s:33:"Pengenceran ke konsentrasi target";i:4;s:27:"Penyimpanan sebelum injeksi";}', 'a:5:{i:0;s:32:"Water filtration and preparation";i:1;s:23:"Polymer powder addition";i:2;s:20:"Mixing and hydration";i:3;s:32:"Dilution to target concentration";i:4;s:24:"Storage before injection";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000868', 'Benarkah polymer flooding dapat menurunkan saturasi minyak sisa (Sor) secara signifikan?', 'Is it true that polymer flooding can significantly reduce residual oil saturation (Sor)?', 'yesorno', 'PFC000000009', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000869', 'Benarkah viskositas larutan polimer dapat menurun akibat degradasi mekanis di pompa?', 'Is it true that polymer solution viscosity can decrease due to mechanical degradation in pumps?', 'yesorno', 'PFC000000009', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000870', 'Surfaktan adalah zat yang dapat...', 'A surfactant is a substance that can...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:51:"Menurunkan tegangan antarmuka antara minyak dan air";i:1;s:30:"Meningkatkan viskositas minyak";i:2;s:26:"Menaikkan porositas batuan";i:3;s:28:"Menurunkan tekanan reservoir";}', 'a:4:{i:0;s:48:"Reduce interfacial tension between oil and water";i:1;s:22:"Increase oil viscosity";i:2;s:22:"Increase rock porosity";i:3;s:24:"Lower reservoir pressure";}', '', 'Menurunkan tegangan antarmuka antara minyak dan air', 'Reduce interfacial tension between oil and water', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000871', 'Molekul surfaktan memiliki bagian...', 'A surfactant molecule has a part that is...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:49:"Hidrofilik (suka air) dan lipofilik (suka minyak)";i:1;s:16:"Hanya hidrofilik";i:2;s:15:"Hanya lipofilik";i:3;s:12:"Bersifat gas";}', 'a:4:{i:0;s:54:"Hydrophilic (water-loving) and lipophilic (oil-loving)";i:1;s:16:"Only hydrophilic";i:2;s:15:"Only lipophilic";i:3;s:7:"Gaseous";}', '', 'Hidrofilik (suka air) dan lipofilik (suka minyak)', 'Hydrophilic (water-loving) and lipophilic (oil-loving)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000872', 'Contoh surfaktan anionik yang umum dipakai pada EOR adalah...', 'An example of an anionic surfactant commonly used in EOR is...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:8:"Sulfonat";i:1;s:4:"NaCl";i:2;s:3:"CO2";i:3;s:6:"Metana";}', 'a:4:{i:0;s:9:"Sulfonate";i:1;s:4:"NaCl";i:2;s:3:"CO2";i:3;s:7:"Methane";}', '', 'Sulfonat', 'Sulfonate', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000873', 'Alkali yang sering digunakan pada alkaline flooding adalah...', 'Alkalis often used in alkaline flooding are...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:15:"NaOH dan Na2CO3";i:1;s:13:"HCl dan H2SO4";i:2;s:10:"CO2 dan N2";i:3;s:12:"CH4 dan C2H6";}', 'a:4:{i:0;s:15:"NaOH and Na2CO3";i:1;s:13:"HCl and H2SO4";i:2;s:10:"CO2 and N2";i:3;s:12:"CH4 and C2H6";}', '', 'NaOH dan Na2CO3', 'NaOH and Na2CO3', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000874', 'Alkaline flooding bekerja melalui pembentukan...', 'Alkaline flooding works through the formation of...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:50:"Surfaktan in-situ dari reaksi dengan asam naftenat";i:1;s:10:"Gas metana";i:2;s:12:"Mineral baru";i:3;s:5:"Semen";}', 'a:4:{i:0;s:55:"In-situ surfactants from reaction with naphthenic acids";i:1;s:11:"Methane gas";i:2;s:12:"New minerals";i:3;s:6:"Cement";}', '', 'Surfaktan in-situ dari reaksi dengan asam naftenat', 'In-situ surfactants from reaction with naphthenic acids', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000875', 'ASP flooding merupakan kombinasi dari...', 'ASP flooding is a combination of...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:32:"Alkaline, Surfaktan, dan Polimer";i:1;s:23:"Air, Steam, dan Polimer";i:2;s:25:"Asam, Sulfur, dan Propana";i:3;s:28:"Alkaline, Steam, dan Propana";}', 'a:4:{i:0;s:33:"Alkaline, Surfactant, and Polymer";i:1;s:23:"Air, Steam, and Polymer";i:2;s:25:"Acid, Sulfur, and Propane";i:3;s:28:"Alkaline, Steam, and Propane";}', '', 'Alkaline, Surfaktan, dan Polimer', 'Alkaline, Surfactant, and Polymer', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000876', 'Mikroemulsi pada surfaktan flooding terbentuk ketika...', 'A microemulsion in surfactant flooding forms when...', 'option', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:57:"Minyak, air, dan surfaktan membentuk fasa campuran stabil";i:1;s:21:"Air dan gas bercampur";i:2;s:22:"Batuan larut dalam air";i:3;s:20:"Polimer terdegradasi";}', 'a:4:{i:0;s:52:"Oil, water, and surfactant form a stable mixed phase";i:1;s:17:"Water and gas mix";i:2;s:23:"Rock dissolves in water";i:3;s:16:"Polymer degrades";}', '', 'Minyak, air, dan surfaktan membentuk fasa campuran stabil', 'Oil, water, and surfactant form a stable mixed phase', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000877', 'Manakah jenis surfaktan yang umum digunakan pada EOR?', 'Which surfactant types are commonly used in EOR?', 'multi', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:7:"Anionik";i:1;s:8:"Nonionik";i:2;s:8:"Kationik";i:3;s:11:"Logam berat";}', 'a:4:{i:0;s:7:"Anionic";i:1;s:8:"Nonionic";i:2;s:8:"Cationic";i:3;s:11:"Heavy metal";}', '', 'a:3:{i:0;s:7:"Anionik";i:1;s:8:"Nonionik";i:2;s:8:"Kationik";}', 'a:3:{i:0;s:7:"Anionic";i:1;s:8:"Nonionic";i:2;s:8:"Cationic";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000878', 'Urutkan urutan injeksi pada proses ASP flooding.', 'Arrange the injection sequence in the ASP flooding process.', 'drag', 'PFC000000010', 'Soal Inisialisasi', 'a:4:{i:0;s:8:"Preflush";i:1;s:23:"Slug alkaline-surfaktan";i:2;s:12:"Slug polimer";i:3;s:11:"Chase water";}', 'a:4:{i:0;s:8:"Preflush";i:1;s:24:"Alkaline-surfactant slug";i:2;s:12:"Polymer slug";i:3;s:11:"Chase water";}', '', 'a:4:{i:0;s:8:"Preflush";i:1;s:23:"Slug alkaline-surfaktan";i:2;s:12:"Slug polimer";i:3;s:11:"Chase water";}', 'a:4:{i:0;s:8:"Preflush";i:1;s:24:"Alkaline-surfactant slug";i:2;s:12:"Polymer slug";i:3;s:11:"Chase water";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000879', 'Benarkah surfaktan dapat menurunkan tegangan antarmuka hingga beberapa orde besaran?', 'Is it true that surfactants can reduce interfacial tension by several orders of magnitude?', 'yesorno', 'PFC000000010', 'Soal Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000880', 'Penurunan IFT dari 30 mN/m menjadi 0,003 mN/m akan menaikkan bilangan kapiler sekitar...', 'Reducing IFT from 30 mN/m to 0.003 mN/m will increase the capillary number by about...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:11:"10.000 kali";i:1;s:8:"100 kali";i:2;s:7:"10 kali";i:3;s:13:"Tidak berubah";}', 'a:4:{i:0;s:12:"10,000 times";i:1;s:9:"100 times";i:2;s:8:"10 times";i:3;s:9:"No change";}', '', '10.000 kali', '10,000 times', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000881', 'Pada klasifikasi Winsor, tipe III menggambarkan sistem...', 'In the Winsor classification, type III describes a system...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:38:"Tiga fasa dengan mikroemulsi di tengah";i:1;s:9:"Satu fasa";i:2;s:30:"Dua fasa dengan minyak di atas";i:3;s:27:"Dua fasa dengan air di atas";}', 'a:4:{i:0;s:47:"Three phases with a microemulsion in the middle";i:1;s:9:"One phase";i:2;s:26:"Two phases with oil on top";i:3;s:28:"Two phases with water on top";}', '', 'Tiga fasa dengan mikroemulsi di tengah', 'Three phases with a microemulsion in the middle', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000882', 'Optimum salinity pada surfaktan flooding adalah kondisi di mana...', 'Optimum salinity in surfactant flooding is the condition where...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:57:"Tegangan antarmuka mencapai minimum dan recovery maksimum";i:1;s:22:"Surfaktan terdegradasi";i:2;s:17:"Polimer mengendap";i:3;s:21:"Tidak ada mikroemulsi";}', 'a:4:{i:0;s:61:"Interfacial tension reaches a minimum and recovery is maximum";i:1;s:19:"Surfactant degrades";i:2;s:20:"Polymer precipitates";i:3;s:22:"No microemulsion forms";}', '', 'Tegangan antarmuka mencapai minimum dan recovery maksimum', 'Interfacial tension reaches a minimum and recovery is maximum', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000883', 'Nilai HLB (hydrophile-lipophile balance) yang tinggi menunjukkan surfaktan lebih...', 'A high HLB (hydrophile-lipophile balance) value indicates the surfactant is more...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:22:"Hidrofilik (larut air)";i:1;s:24:"Lipofilik (larut minyak)";i:2;s:12:"Bersifat gas";i:3;s:23:"Tidak larut sama sekali";}', 'a:4:{i:0;s:27:"Hydrophilic (water-soluble)";i:1;s:24:"Lipophilic (oil-soluble)";i:2;s:7:"Gaseous";i:3;s:20:"Completely insoluble";}', '', 'Hidrofilik (larut air)', 'Hydrophilic (water-soluble)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000884', 'Konsumsi alkali di reservoir terutama disebabkan oleh...', 'Alkali consumption in the reservoir is mainly caused by...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:44:"Reaksi dengan mineral batuan dan ion divalen";i:1;s:18:"Penguapan ke udara";i:2;s:15:"Pembentukan gas";i:3;s:32:"Pencampuran dengan minyak ringan";}', 'a:4:{i:0;s:46:"Reactions with rock minerals and divalent ions";i:1;s:22:"Evaporation to the air";i:2;s:13:"Gas formation";i:3;s:21:"Mixing with light oil";}', '', 'Reaksi dengan mineral batuan dan ion divalen', 'Reactions with rock minerals and divalent ions', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000885', 'Risiko utama injeksi alkali pada batupasir adalah...', 'The main risk of alkali injection in sandstone is...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:39:"Pembentukan scale dan kerusakan formasi";i:1;s:21:"Peningkatan porositas";i:2;s:24:"Penurunan viskositas air";i:3;s:25:"Peningkatan permeabilitas";}', 'a:4:{i:0;s:36:"Scale formation and formation damage";i:1;s:18:"Increased porosity";i:2;s:23:"Reduced water viscosity";i:3;s:22:"Increased permeability";}', '', 'Pembentukan scale dan kerusakan formasi', 'Scale formation and formation damage', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000886', 'Surfaktan flooding umumnya paling efektif bila diikuti oleh...', 'Surfactant flooding is generally most effective when followed by...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:42:"Slug polimer untuk mengendalikan mobilitas";i:1;s:15:"Injeksi gas CO2";i:2;s:22:"Air tawar tanpa aditif";i:3;s:5:"Semen";}', 'a:4:{i:0;s:35:"A polymer slug for mobility control";i:1;s:17:"CO2 gas injection";i:2;s:29:"Fresh water without additives";i:3;s:6:"Cement";}', '', 'Slug polimer untuk mengendalikan mobilitas', 'A polymer slug for mobility control', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000887', 'Surfaktan anionik umumnya kurang cocok pada air formasi dengan...', 'Anionic surfactants are generally less suitable in formation water with...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:34:"Kadar kalsium dan magnesium tinggi";i:1;s:16:"Salinitas rendah";i:2;s:11:"Suhu rendah";i:3;s:9:"pH netral";}', 'a:4:{i:0;s:34:"High calcium and magnesium content";i:1;s:12:"Low salinity";i:2;s:15:"Low temperature";i:3;s:10:"Neutral pH";}', '', 'Kadar kalsium dan magnesium tinggi', 'High calcium and magnesium content', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000888', 'Adsorpsi surfaktan pada batuan menyebabkan...', 'Surfactant adsorption on rock causes...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:57:"Kehilangan surfaktan sehingga slug menjadi kurang efektif";i:1;s:33:"Peningkatan konsentrasi surfaktan";i:2;s:15:"Peningkatan IFT";i:3;s:21:"Peningkatan porositas";}', 'a:4:{i:0;s:50:"Surfactant loss so the slug becomes less effective";i:1;s:34:"Increased surfactant concentration";i:2;s:13:"Increased IFT";i:3;s:18:"Increased porosity";}', '', 'Kehilangan surfaktan sehingga slug menjadi kurang efektif', 'Surfactant loss so the slug becomes less effective', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000889', 'Pada alkaline flooding, penurunan IFT terjadi karena...', 'In alkaline flooding, IFT reduction occurs because...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:51:"Terbentuk surfaktan alami (soap) dari asam naftenat";i:1;s:17:"Terbentuk gas CO2";i:2;s:31:"Alkali menaikkan viskositas air";i:3;s:24:"Alkali melarutkan kuarsa";}', 'a:4:{i:0;s:53:"Natural surfactants (soap) form from naphthenic acids";i:1;s:13:"CO2 gas forms";i:2;s:32:"Alkali increases water viscosity";i:3;s:23:"Alkali dissolves quartz";}', '', 'Terbentuk surfaktan alami (soap) dari asam naftenat', 'Natural surfactants (soap) form from naphthenic acids', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000890', 'Kombinasi alkali dan surfaktan bersifat sinergis karena...', 'The combination of alkali and surfactant is synergistic because...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:67:"Alkali menurunkan adsorpsi surfaktan dan menambah surfaktan in-situ";i:1;s:20:"Alkali menaikkan IFT";i:2;s:36:"Alkali menurunkan viskositas polimer";i:3;s:27:"Alkali menghilangkan minyak";}', 'a:4:{i:0;s:64:"Alkali reduces surfactant adsorption and adds in-situ surfactant";i:1;s:20:"Alkali increases IFT";i:2;s:32:"Alkali reduces polymer viscosity";i:3;s:22:"Alkali removes the oil";}', '', 'Alkali menurunkan adsorpsi surfaktan dan menambah surfaktan in-situ', 'Alkali reduces surfactant adsorption and adds in-situ surfactant', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000891', 'Surfaktan flooding pada reservoir karbonat umumnya lebih menantang karena...', 'Surfactant flooding in carbonate reservoirs is generally more challenging because...', 'option', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:77:"Permukaan batuan cenderung positif sehingga adsorpsi surfaktan anionik tinggi";i:1;s:24:"Porositas terlalu tinggi";i:2;s:16:"Tidak ada minyak";i:3;s:18:"Suhu selalu rendah";}', 'a:4:{i:0;s:74:"Rock surfaces tend to be positive so anionic surfactant adsorption is high";i:1;s:20:"Porosity is too high";i:2;s:15:"There is no oil";i:3;s:25:"Temperature is always low";}', '', 'Permukaan batuan cenderung positif sehingga adsorpsi surfaktan anionik tinggi', 'Rock surfaces tend to be positive so anionic surfactant adsorption is high', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000892', 'Manakah mekanisme yang berperan pada alkaline flooding?', 'Which mechanisms play a role in alkaline flooding?', 'multi', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:39:"Penurunan IFT melalui surfaktan in-situ";i:1;s:21:"Perubahan wettability";i:2;s:12:"Emulsifikasi";i:3;s:29:"Peningkatan viskositas minyak";}', 'a:4:{i:0;s:41:"IFT reduction through in-situ surfactants";i:1;s:22:"Wettability alteration";i:2;s:14:"Emulsification";i:3;s:24:"Increasing oil viscosity";}', '', 'a:3:{i:0;s:39:"Penurunan IFT melalui surfaktan in-situ";i:1;s:21:"Perubahan wettability";i:2;s:12:"Emulsifikasi";}', 'a:3:{i:0;s:41:"IFT reduction through in-situ surfactants";i:1;s:22:"Wettability alteration";i:2;s:14:"Emulsification";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000893', 'Manakah faktor yang memengaruhi desain slug surfaktan?', 'Which factors affect surfactant slug design?', 'multi', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:26:"Salinitas dan hardness air";i:1;s:14:"Suhu reservoir";i:2;s:31:"Jenis dan konsentrasi surfaktan";i:3;s:12:"Warna batuan";}', 'a:4:{i:0;s:27:"Water salinity and hardness";i:1;s:21:"Reservoir temperature";i:2;s:33:"Surfactant type and concentration";i:3;s:10:"Rock color";}', '', 'a:3:{i:0;s:26:"Salinitas dan hardness air";i:1;s:14:"Suhu reservoir";i:2;s:31:"Jenis dan konsentrasi surfaktan";}', 'a:3:{i:0;s:27:"Water salinity and hardness";i:1;s:21:"Reservoir temperature";i:2;s:33:"Surfactant type and concentration";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000894', 'Manakah fungsi polimer dalam proses ASP?', 'Which are the functions of polymer in the ASP process?', 'multi', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:39:"Mengendalikan mobilitas fluida pendesak";i:1;s:28:"Meningkatkan efisiensi sweep";i:2;s:20:"Mengurangi fingering";i:3;s:30:"Menurunkan IFT secara langsung";}', 'a:4:{i:0;s:44:"Control the mobility of the displacing fluid";i:1;s:24:"Improve sweep efficiency";i:2;s:16:"Reduce fingering";i:3;s:19:"Directly reduce IFT";}', '', 'a:3:{i:0;s:39:"Mengendalikan mobilitas fluida pendesak";i:1;s:28:"Meningkatkan efisiensi sweep";i:2;s:20:"Mengurangi fingering";}', 'a:3:{i:0;s:44:"Control the mobility of the displacing fluid";i:1;s:24:"Improve sweep efficiency";i:2;s:16:"Reduce fingering";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000895', 'Manakah keterbatasan alkaline flooding?', 'Which are limitations of alkaline flooding?', 'multi', 'PFC000000010', 'Final Test Advanced', 'a:4:{i:0;s:42:"Konsumsi alkali tinggi pada batuan reaktif";i:1;s:12:"Risiko scale";i:2;s:45:"Tidak efektif pada minyak tanpa asam naftenat";i:3;s:30:"Selalu menaikkan permeabilitas";}', 'a:4:{i:0;s:41:"High alkali consumption in reactive rocks";i:1;s:10:"Scale risk";i:2;s:45:"Ineffective for oils without naphthenic acids";i:3;s:29:"Always increases permeability";}', '', 'a:3:{i:0;s:42:"Konsumsi alkali tinggi pada batuan reaktif";i:1;s:12:"Risiko scale";i:2;s:45:"Tidak efektif pada minyak tanpa asam naftenat";}', 'a:3:{i:0;s:41:"High alkali consumption in reactive rocks";i:1;s:10:"Scale risk";i:2;s:45:"Ineffective for oils without naphthenic acids";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000896', 'Urutkan tahapan uji surfaktan di laboratorium.', 'Arrange the laboratory surfactant testing stages.', 'drag', 'PFC000000010', 'Final Test Advanced', 'a:5:{i:0;s:28:"Uji tegangan antarmuka (IFT)";i:1;s:38:"Uji perilaku fasa dan optimum salinity";i:2;s:24:"Uji adsorpsi pada batuan";i:3;s:14:"Uji core flood";i:4;s:24:"Simulasi dan desain slug";}', 'a:5:{i:0;s:30:"Interfacial tension (IFT) test";i:1;s:40:"Phase behavior and optimum salinity test";i:2;s:20:"Rock adsorption test";i:3;s:15:"Core flood test";i:4;s:26:"Simulation and slug design";}', '', 'a:5:{i:0;s:28:"Uji tegangan antarmuka (IFT)";i:1;s:38:"Uji perilaku fasa dan optimum salinity";i:2;s:24:"Uji adsorpsi pada batuan";i:3;s:14:"Uji core flood";i:4;s:24:"Simulasi dan desain slug";}', 'a:5:{i:0;s:30:"Interfacial tension (IFT) test";i:1;s:40:"Phase behavior and optimum salinity test";i:2;s:20:"Rock adsorption test";i:3;s:15:"Core flood test";i:4;s:26:"Simulation and slug design";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000897', 'Urutkan tipe Winsor dari kondisi surfaktan larut minyak ke larut air.', 'Arrange the Winsor types from oil-soluble surfactant conditions to water-soluble.', 'drag', 'PFC000000010', 'Final Test Advanced', 'a:3:{i:0;s:34:"Winsor II (surfaktan larut minyak)";i:1;s:31:"Winsor III (mikroemulsi tengah)";i:2;s:30:"Winsor I (surfaktan larut air)";}', 'a:3:{i:0;s:34:"Winsor II (oil-soluble surfactant)";i:1;s:33:"Winsor III (middle microemulsion)";i:2;s:35:"Winsor I (water-soluble surfactant)";}', '', 'a:3:{i:0;s:34:"Winsor II (surfaktan larut minyak)";i:1;s:31:"Winsor III (mikroemulsi tengah)";i:2;s:30:"Winsor I (surfaktan larut air)";}', 'a:3:{i:0;s:34:"Winsor II (oil-soluble surfactant)";i:1;s:33:"Winsor III (middle microemulsion)";i:2;s:35:"Winsor I (water-soluble surfactant)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000898', 'Benarkah surfaktan bekerja dengan mengubah wettability batuan dan menurunkan IFT sekaligus?', 'Is it true that surfactants work by altering rock wettability and reducing IFT at the same time?', 'yesorno', 'PFC000000010', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000899', 'Benarkah alkali selalu meningkatkan viskositas larutan secara signifikan?', 'Is it true that alkali always significantly increases solution viscosity?', 'yesorno', 'PFC000000010', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000900', 'Prinsip utama thermal EOR adalah...', 'The main principle of thermal EOR is...', 'option', 'PFC000000011', 'Soal Inisialisasi', 'a:4:{i:0;s:55:"Memanaskan reservoir untuk menurunkan viskositas minyak";i:1;s:22:"Mendinginkan reservoir";i:2;s:27:"Menambah tekanan overburden";i:3;s:20:"Menurunkan porositas";}', 'a:4:{i:0;s:45:"Heating the reservoir to reduce oil viscosity";i:1;s:21:"Cooling the reservoir";i:2;s:30:"Increasing overburden pressure";i:3;s:17:"Reducing porosity";}', '', 'Memanaskan reservoir untuk menurunkan viskositas minyak', 'Heating the reservoir to reduce oil viscosity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000901', 'Steam flooding dilakukan dengan cara...', 'Steam flooding is performed by...', 'option', 'PFC000000011', 'Soal Inisialisasi', 'a:4:{i:0;s:57:"Menginjeksikan steam secara kontinu melalui sumur injeksi";i:1;s:25:"Menginjeksikan air dingin";i:2;s:27:"Menginjeksikan gas nitrogen";i:3;s:22:"Menginjeksikan polimer";}', 'a:4:{i:0;s:54:"Continuously injecting steam through an injection well";i:1;s:20:"Injecting cold water";i:2;s:22:"Injecting nitrogen gas";i:3;s:17:"Injecting polymer";}', '', 'Menginjeksikan steam secara kontinu melalui sumur injeksi', 'Continuously injecting steam through an injection well', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000902', 'Cyclic steam stimulation (CSS) juga dikenal sebagai...', 'Cyclic steam stimulation (CSS) is also known as...', 'option', 'PFC000000011', 'Soal Inisialisasi', 'a:4:{i:0;s:13:"Huff and puff";i:1;s:10:"Waterflood";i:2;s:3:"WAG";i:3;s:19:"Surfactant flooding";}', 'a:4:{i:0;s:13:"Huff and puff";i:1;s:10:"Waterflood";i:2;s:3:"WAG";i:3;s:19:"Surfactant flooding";}', '', 'Huff and puff', 'Huff and puff', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000903', 'SAGD menggunakan...', 'SAGD uses...', 'option', 'PFC000000011', 'Soal Inisialisasi', 'a:4:{i:0;s:48:"Sepasang sumur horizontal (injeksi dan produksi)";i:1;s:19:"Satu sumur vertikal";i:2;s:20:"Empat sumur vertikal";i:3;s:32:"Sumur multilateral tanpa injeksi";}', 'a:4:{i:0;s:50:"A pair of horizontal wells (injector and producer)";i:1;s:17:"One vertical well";i:2;s:19:"Four vertical wells";i:3;s:36:"Multilateral wells without injection";}', '', 'Sepasang sumur horizontal (injeksi dan produksi)', 'A pair of horizontal wells (injector and producer)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000904', 'In-situ combustion adalah metode di mana...', 'In-situ combustion is a method where...', 'option', 'PFC000000011', 'Soal Inisialisasi', 'a:4:{i:0;s:61:"Sebagian minyak dibakar di reservoir untuk menghasilkan panas";i:1;s:27:"Air dipanaskan di permukaan";i:2;s:20:"Gas dibakar di flare";i:3;s:32:"Batuan dipanaskan dengan listrik";}', 'a:4:{i:0;s:59:"Part of the oil is burned in the reservoir to generate heat";i:1;s:30:"Water is heated at the surface";i:2;s:24:"Gas is burned in a flare";i:3;s:31:"The rock is heated electrically";}', '', 'Sebagian minyak dibakar di reservoir untuk menghasilkan panas', 'Part of the oil is burned in the reservoir to generate heat', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000905', 'Gas yang paling umum digunakan pada gas EOR untuk pencampuran (miscible) adalah...', 'The gas most commonly used in gas EOR for miscibility is...', 'option', 'PFC000000011', 'Soal Inisialisasi', 'a:4:{i:0;s:3:"CO2";i:1;s:6:"Helium";i:2;s:5:"Argon";i:3;s:5:"Udara";}', 'a:4:{i:0;s:3:"CO2";i:1;s:6:"Helium";i:2;s:5:"Argon";i:3;s:3:"Air";}', '', 'CO2', 'CO2', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000906', 'Injeksi gas dikatakan miscible apabila...', 'Gas injection is said to be miscible when...', 'option', 'PFC000000011', 'Soal Inisialisasi', 'a:4:{i:0;s:49:"Gas dan minyak bercampur tanpa tegangan antarmuka";i:1;s:32:"Gas dan minyak terpisah sempurna";i:2;s:28:"Gas tidak larut dalam minyak";i:3;s:16:"Tidak ada aliran";}', 'a:4:{i:0;s:43:"Gas and oil mix without interfacial tension";i:1;s:31:"Gas and oil separate completely";i:2;s:28:"Gas does not dissolve in oil";i:3;s:16:"There is no flow";}', '', 'Gas dan minyak bercampur tanpa tegangan antarmuka', 'Gas and oil mix without interfacial tension', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000907', 'Manakah yang termasuk metode thermal EOR?', 'Which of the following are thermal EOR methods?', 'multi', 'PFC000000011', 'Soal Inisialisasi', 'a:4:{i:0;s:14:"Steam flooding";i:1;s:24:"Cyclic steam stimulation";i:2;s:18:"In-situ combustion";i:3;s:16:"Polymer flooding";}', 'a:4:{i:0;s:14:"Steam flooding";i:1;s:24:"Cyclic steam stimulation";i:2;s:18:"In-situ combustion";i:3;s:16:"Polymer flooding";}', '', 'a:3:{i:0;s:14:"Steam flooding";i:1;s:24:"Cyclic steam stimulation";i:2;s:18:"In-situ combustion";}', 'a:3:{i:0;s:14:"Steam flooding";i:1;s:24:"Cyclic steam stimulation";i:2;s:18:"In-situ combustion";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000908', 'Urutkan tahapan siklus CSS (cyclic steam stimulation).', 'Arrange the stages of the CSS (cyclic steam stimulation) cycle.', 'drag', 'PFC000000011', 'Soal Inisialisasi', 'a:4:{i:0;s:20:"Injeksi steam (huff)";i:1;s:15:"Periode soaking";i:2;s:15:"Produksi (puff)";i:3;s:29:"Pengulangan siklus berikutnya";}', 'a:4:{i:0;s:22:"Steam injection (huff)";i:1;s:14:"Soaking period";i:2;s:17:"Production (puff)";i:3;s:28:"Repetition of the next cycle";}', '', 'a:4:{i:0;s:20:"Injeksi steam (huff)";i:1;s:15:"Periode soaking";i:2;s:15:"Produksi (puff)";i:3;s:29:"Pengulangan siklus berikutnya";}', 'a:4:{i:0;s:22:"Steam injection (huff)";i:1;s:14:"Soaking period";i:2;s:17:"Production (puff)";i:3;s:28:"Repetition of the next cycle";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000909', 'Benarkah thermal EOR lebih cocok untuk minyak berat dengan viskositas tinggi?', 'Is it true that thermal EOR is more suitable for heavy oil with high viscosity?', 'yesorno', 'PFC000000011', 'Soal Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000910', 'Kenaikan suhu reservoir dari 40 °C ke 200 °C pada minyak berat umumnya menurunkan viskositas hingga...', 'Raising reservoir temperature from 40 °C to 200 °C in heavy oil generally reduces viscosity by up to...', 'option', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:50:"Beberapa orde besaran (ratusan hingga ribuan kali)";i:1;s:12:"Hanya 2 kali";i:2;s:13:"Tidak berubah";i:3;s:20:"Menjadi lebih tinggi";}', 'a:4:{i:0;s:60:"Several orders of magnitude (hundreds to thousands of times)";i:1;s:12:"Only 2 times";i:2;s:9:"No change";i:3;s:15:"Becoming higher";}', '', 'Beberapa orde besaran (ratusan hingga ribuan kali)', 'Several orders of magnitude (hundreds to thousands of times)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000911', 'Steam quality (kualitas steam) menyatakan...', 'Steam quality expresses...', 'option', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:47:"Fraksi massa steam (uap) dalam campuran uap-air";i:1;s:10:"Suhu steam";i:2;s:13:"Tekanan steam";i:3;s:17:"Kecepatan injeksi";}', 'a:4:{i:0;s:61:"The mass fraction of steam (vapor) in the steam-water mixture";i:1;s:17:"Steam temperature";i:2;s:14:"Steam pressure";i:3;s:14:"Injection rate";}', '', 'Fraksi massa steam (uap) dalam campuran uap-air', 'The mass fraction of steam (vapor) in the steam-water mixture', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000912', 'Steam-oil ratio (SOR) adalah...', 'The steam-oil ratio (SOR) is...', 'option', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:61:"Volume steam yang diinjeksi per volume minyak yang diproduksi";i:1;s:35:"Perbandingan minyak dan air formasi";i:2;s:29:"Perbandingan tekanan dan suhu";i:3;s:27:"Perbandingan gas dan minyak";}', 'a:4:{i:0;s:55:"The volume of steam injected per volume of oil produced";i:1;s:35:"The ratio of oil to formation water";i:2;s:36:"The ratio of pressure to temperature";i:3;s:23:"The ratio of gas to oil";}', '', 'Volume steam yang diinjeksi per volume minyak yang diproduksi', 'The volume of steam injected per volume of oil produced', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000913', 'Minimum miscibility pressure (MMP) adalah tekanan minimum agar...', 'Minimum miscibility pressure (MMP) is the minimum pressure for...', 'option', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:44:"Gas dan minyak tercampur sempurna (miscible)";i:1;s:12:"Air mendidih";i:2;s:12:"Batuan retak";i:3;s:13:"Polimer larut";}', 'a:4:{i:0;s:36:"Gas and oil to become fully miscible";i:1;s:13:"Water to boil";i:2;s:20:"The rock to fracture";i:3;s:19:"Polymer to dissolve";}', '', 'Gas dan minyak tercampur sempurna (miscible)', 'Gas and oil to become fully miscible', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000914', 'CO2 miscible flooding umumnya memerlukan tekanan reservoir...', 'CO2 miscible flooding generally requires reservoir pressure...', 'option', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:11:"Di atas MMP";i:1;s:12:"Di bawah MMP";i:2;s:28:"Sama dengan tekanan atmosfer";i:3;s:24:"Tidak bergantung tekanan";}', 'a:4:{i:0;s:13:"Above the MMP";i:1;s:13:"Below the MMP";i:2;s:29:"Equal to atmospheric pressure";i:3;s:23:"Independent of pressure";}', '', 'Di atas MMP', 'Above the MMP', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000915', 'Masalah utama injeksi gas pada reservoir minyak adalah...', 'The main problem with gas injection in oil reservoirs is...', 'option', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:66:"Viscous fingering dan gravity override akibat mobilitas gas tinggi";i:1;s:17:"Gas terlalu berat";i:2;s:24:"Gas tidak dapat mengalir";i:3;s:31:"Gas menaikkan viskositas minyak";}', 'a:4:{i:0;s:63:"Viscous fingering and gravity override due to high gas mobility";i:1;s:16:"Gas is too heavy";i:2;s:15:"Gas cannot flow";i:3;s:27:"Gas increases oil viscosity";}', '', 'Viscous fingering dan gravity override akibat mobilitas gas tinggi', 'Viscous fingering and gravity override due to high gas mobility', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000916', 'Metode WAG (water alternating gas) dilakukan untuk...', 'The WAG (water alternating gas) method is applied to...', 'option', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:46:"Mengurangi fingering gas dan memperbaiki sweep";i:1;s:24:"Menaikkan viskositas gas";i:2;s:28:"Menurunkan tekanan reservoir";i:3;s:21:"Menambah produksi air";}', 'a:4:{i:0;s:38:"Reduce gas fingering and improve sweep";i:1;s:22:"Increase gas viscosity";i:2;s:24:"Lower reservoir pressure";i:3;s:25:"Increase water production";}', '', 'Mengurangi fingering gas dan memperbaiki sweep', 'Reduce gas fingering and improve sweep', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000917', 'Pada in-situ combustion, zona di depan front pembakaran tempat minyak ringan menguap disebut...', 'In in-situ combustion, the zone ahead of the combustion front where light oil vaporizes is called...', 'option', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:29:"Zona distilasi (vaporization)";i:1;s:13:"Zona terbakar";i:2;s:8:"Zona air";i:3;s:15:"Zona overburden";}', 'a:4:{i:0;s:32:"Distillation (vaporization) zone";i:1;s:11:"Burned zone";i:2;s:10:"Water zone";i:3;s:15:"Overburden zone";}', '', 'Zona distilasi (vaporization)', 'Distillation (vaporization) zone', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000918', 'Kehilangan panas (heat loss) pada steam flooding terutama terjadi melalui...', 'Heat loss in steam flooding mainly occurs through...', 'option', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:41:"Konduksi ke formasi sekitar dan permukaan";i:1;s:18:"Radiasi ke angkasa";i:2;s:14:"Aliran listrik";i:3;s:17:"Pendinginan pompa";}', 'a:4:{i:0;s:52:"Conduction to surrounding formations and the surface";i:1;s:20:"Radiation to the sky";i:2;s:18:"Electrical current";i:3;s:12:"Pump cooling";}', '', 'Konduksi ke formasi sekitar dan permukaan', 'Conduction to surrounding formations and the surface', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000919', 'Injeksi CO2 juga menurunkan viskositas minyak karena...', 'CO2 injection also reduces oil viscosity because...', 'option', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:22:"CO2 larut dalam minyak";i:1;s:21:"CO2 membekukan minyak";i:2;s:22:"CO2 mengubah porositas";i:3;s:20:"CO2 menambah lempung";}', 'a:4:{i:0;s:24:"CO2 dissolves in the oil";i:1;s:19:"CO2 freezes the oil";i:2;s:20:"CO2 changes porosity";i:3;s:13:"CO2 adds clay";}', '', 'CO2 larut dalam minyak', 'CO2 dissolves in the oil', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000920', 'Kebutuhan udara (air requirement) pada in-situ combustion dinyatakan sebagai...', 'Air requirement in in-situ combustion is expressed as...', 'option', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:46:"Volume udara per volume minyak yang diproduksi";i:1;s:24:"Perbandingan gas dan air";i:2;s:13:"Tekanan udara";i:3;s:15:"Kecepatan kipas";}', 'a:4:{i:0;s:40:"Volume of air per volume of oil produced";i:1;s:25:"The ratio of gas to water";i:2;s:12:"Air pressure";i:3;s:9:"Fan speed";}', '', 'Volume udara per volume minyak yang diproduksi', 'Volume of air per volume of oil produced', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000921', 'Thermal EOR umumnya kurang cocok pada reservoir yang...', 'Thermal EOR is generally less suitable for reservoirs that are...', 'option', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:44:"Sangat tipis dengan lapisan overburden tipis";i:1;s:15:"Tebal dan dalam";i:2;s:23:"Mengandung minyak berat";i:3;s:26:"Memiliki viskositas tinggi";}', 'a:4:{i:0;s:32:"Very thin with a thin overburden";i:1;s:14:"Thick and deep";i:2;s:20:"Containing heavy oil";i:3;s:21:"Having high viscosity";}', '', 'Sangat tipis dengan lapisan overburden tipis', 'Very thin with a thin overburden', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000922', 'Manakah faktor yang memengaruhi kelayakan steam flooding?', 'Which factors affect the feasibility of steam flooding?', 'multi', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:41:"Kedalaman reservoir (tekanan hidrostatik)";i:1;s:19:"Ketebalan reservoir";i:2;s:36:"Viskositas minyak dan kualitas steam";i:3;s:12:"Warna batuan";}', 'a:4:{i:0;s:38:"Reservoir depth (hydrostatic pressure)";i:1;s:19:"Reservoir thickness";i:2;s:31:"Oil viscosity and steam quality";i:3;s:10:"Rock color";}', '', 'a:3:{i:0;s:41:"Kedalaman reservoir (tekanan hidrostatik)";i:1;s:19:"Ketebalan reservoir";i:2;s:36:"Viskositas minyak dan kualitas steam";}', 'a:3:{i:0;s:38:"Reservoir depth (hydrostatic pressure)";i:1;s:19:"Reservoir thickness";i:2;s:31:"Oil viscosity and steam quality";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000923', 'Manakah mekanisme peningkatan perolehan pada injeksi CO2?', 'Which are oil recovery mechanisms in CO2 injection?', 'multi', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:39:"Pencampuran (miscibility) dengan minyak";i:1;s:27:"Penurunan viskositas minyak";i:2;s:29:"Peningkatan tekanan reservoir";i:3;s:29:"Peningkatan viskositas minyak";}', 'a:4:{i:0;s:20:"Miscibility with oil";i:1;s:26:"Reduction of oil viscosity";i:2;s:30:"Increase in reservoir pressure";i:3;s:25:"Increase in oil viscosity";}', '', 'a:3:{i:0;s:39:"Pencampuran (miscibility) dengan minyak";i:1;s:27:"Penurunan viskositas minyak";i:2;s:29:"Peningkatan tekanan reservoir";}', 'a:3:{i:0;s:20:"Miscibility with oil";i:1;s:26:"Reduction of oil viscosity";i:2;s:30:"Increase in reservoir pressure";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000924', 'Manakah tantangan operasional in-situ combustion?', 'Which are operational challenges of in-situ combustion?', 'multi', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:30:"Kontrol front pembakaran sulit";i:1;s:27:"Risiko ledakan di permukaan";i:2;s:29:"Kualitas gas buang dan korosi";i:3;s:32:"Peningkatan porositas berlebihan";}', 'a:4:{i:0;s:41:"Difficult control of the combustion front";i:1;s:22:"Surface explosion risk";i:2;s:33:"Exhaust gas quality and corrosion";i:3;s:27:"Excessive porosity increase";}', '', 'a:3:{i:0;s:30:"Kontrol front pembakaran sulit";i:1;s:27:"Risiko ledakan di permukaan";i:2;s:29:"Kualitas gas buang dan korosi";}', 'a:3:{i:0;s:41:"Difficult control of the combustion front";i:1;s:22:"Surface explosion risk";i:2;s:33:"Exhaust gas quality and corrosion";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000925', 'Manakah pernyataan yang benar tentang gas EOR?', 'Which statements about gas EOR are correct?', 'multi', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:54:"Gas memiliki mobilitas tinggi sehingga mudah fingering";i:1;s:45:"MMP bergantung pada komposisi minyak dan suhu";i:2;s:37:"WAG digunakan untuk memperbaiki sweep";i:3;s:41:"Gas selalu meningkatkan viskositas minyak";}', 'a:4:{i:0;s:42:"Gas has high mobility so it fingers easily";i:1;s:46:"MMP depends on oil composition and temperature";i:2;s:28:"WAG is used to improve sweep";i:3;s:34:"Gas always increases oil viscosity";}', '', 'a:3:{i:0;s:54:"Gas memiliki mobilitas tinggi sehingga mudah fingering";i:1;s:45:"MMP bergantung pada komposisi minyak dan suhu";i:2;s:37:"WAG digunakan untuk memperbaiki sweep";}', 'a:3:{i:0;s:42:"Gas has high mobility so it fingers easily";i:1;s:46:"MMP depends on oil composition and temperature";i:2;s:28:"WAG is used to improve sweep";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000926', 'Urutkan zona in-situ combustion dari sumur injeksi ke arah depan.', 'Arrange the in-situ combustion zones from the injection well outward.', 'drag', 'PFC000000011', 'Final Test Advanced', 'a:4:{i:0;s:13:"Zona terbakar";i:1;s:14:"Zona distilasi";i:2;s:23:"Zona kondensasi uap air";i:3;s:27:"Zona minyak tak terpanaskan";}', 'a:4:{i:0;s:11:"Burned zone";i:1;s:17:"Distillation zone";i:2;s:23:"Steam condensation zone";i:3;s:17:"Unheated oil zone";}', '', 'a:4:{i:0;s:13:"Zona terbakar";i:1;s:14:"Zona distilasi";i:2;s:23:"Zona kondensasi uap air";i:3;s:27:"Zona minyak tak terpanaskan";}', 'a:4:{i:0;s:11:"Burned zone";i:1;s:17:"Distillation zone";i:2;s:23:"Steam condensation zone";i:3;s:17:"Unheated oil zone";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
