INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000928', 'Benarkah steam flooding pada reservoir yang sangat dalam menjadi kurang efisien karena kehilangan panas dan tekanan hidrostatik tinggi?', 'Is it true that steam flooding in very deep reservoirs becomes less efficient due to heat loss and high hydrostatic pressure?', 'yesorno', 'PFC000000011', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000929', 'Benarkah injeksi CO2 selalu berada dalam kondisi miscible pada semua tekanan reservoir?', 'Is it true that CO2 injection is always miscible at all reservoir pressures?', 'yesorno', 'PFC000000011', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000930', 'Tujuan utama evaluasi ekonomi proyek EOR adalah...', 'The main purpose of EOR project economic evaluation is...', 'option', 'PFC000000012', 'Soal Inisialisasi', 'a:4:{i:0;s:49:"Menilai kelayakan investasi dan keuntungan proyek";i:1;s:20:"Menentukan warna map";i:2;s:25:"Menghitung jumlah pekerja";i:3;s:22:"Menentukan merek pompa";}', 'a:4:{i:0;s:55:"Assess investment feasibility and project profitability";i:1;s:19:"Determine map color";i:2;s:27:"Count the number of workers";i:3;s:19:"Choose a pump brand";}', '', 'Menilai kelayakan investasi dan keuntungan proyek', 'Assess investment feasibility and project profitability', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000931', 'NPV adalah singkatan dari...', 'NPV stands for...', 'option', 'PFC000000012', 'Soal Inisialisasi', 'a:4:{i:0;s:17:"Net Present Value";i:1;s:21:"New Production Volume";i:2;s:25:"Natural Polymer Viscosity";i:3;s:21:"Normal Pressure Value";}', 'a:4:{i:0;s:17:"Net Present Value";i:1;s:21:"New Production Volume";i:2;s:25:"Natural Polymer Viscosity";i:3;s:21:"Normal Pressure Value";}', '', 'Net Present Value', 'Net Present Value', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000932', 'IRR adalah...', 'IRR is...', 'option', 'PFC000000012', 'Soal Inisialisasi', 'a:4:{i:0;s:41:"Tingkat diskonto saat NPV sama dengan nol";i:1;s:18:"Total biaya proyek";i:2;s:22:"Volume minyak tambahan";i:3;s:12:"Laju injeksi";}', 'a:4:{i:0;s:42:"The discount rate at which NPV equals zero";i:1;s:18:"Total project cost";i:2;s:22:"Incremental oil volume";i:3;s:14:"Injection rate";}', '', 'Tingkat diskonto saat NPV sama dengan nol', 'The discount rate at which NPV equals zero', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000933', 'Pilot test pada proyek EOR bertujuan untuk...', 'A pilot test in an EOR project aims to...', 'option', 'PFC000000012', 'Soal Inisialisasi', 'a:4:{i:0;s:50:"Mengurangi risiko sebelum implementasi skala penuh";i:1;s:31:"Menggantikan simulasi reservoir";i:2;s:30:"Menghindari studi laboratorium";i:3;s:23:"Menentukan harga minyak";}', 'a:4:{i:0;s:44:"Reduce risk before full-scale implementation";i:1;s:28:"Replace reservoir simulation";i:2;s:24:"Avoid laboratory studies";i:3;s:20:"Determine oil prices";}', '', 'Mengurangi risiko sebelum implementasi skala penuh', 'Reduce risk before full-scale implementation', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000934', 'Incremental oil adalah...', 'Incremental oil is...', 'option', 'PFC000000012', 'Soal Inisialisasi', 'a:4:{i:0;s:74:"Minyak tambahan yang diperoleh akibat proyek EOR dibandingkan tanpa proyek";i:1;s:18:"Minyak yang hilang";i:2;s:24:"Total produksi kumulatif";i:3;s:16:"Minyak di tangki";}', 'a:4:{i:0;s:69:"Additional oil obtained from the EOR project compared with no project";i:1;s:8:"Lost oil";i:2;s:27:"Total cumulative production";i:3;s:15:"Oil in the tank";}', '', 'Minyak tambahan yang diperoleh akibat proyek EOR dibandingkan tanpa proyek', 'Additional oil obtained from the EOR project compared with no project', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000935', 'CAPEX adalah biaya...', 'CAPEX is the cost of...', 'option', 'PFC000000012', 'Soal Inisialisasi', 'a:4:{i:0;s:20:"Investasi modal awal";i:1;s:18:"Operasional harian";i:2;s:5:"Pajak";i:3;s:8:"Asuransi";}', 'a:4:{i:0;s:26:"Initial capital investment";i:1;s:16:"Daily operations";i:2;s:3:"Tax";i:3;s:9:"Insurance";}', '', 'Investasi modal awal', 'Initial capital investment', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
