INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000937', 'Manakah indikator ekonomi yang biasa dipakai menilai proyek EOR?', 'Which economic indicators are commonly used to evaluate EOR projects?', 'multi', 'PFC000000012', 'Soal Inisialisasi', 'a:4:{i:0;s:3:"NPV";i:1;s:3:"IRR";i:2;s:14:"Payback period";i:3;s:12:"Warna minyak";}', 'a:4:{i:0;s:3:"NPV";i:1;s:3:"IRR";i:2;s:14:"Payback period";i:3;s:9:"Oil color";}', '', 'a:3:{i:0;s:3:"NPV";i:1;s:3:"IRR";i:2;s:14:"Payback period";}', 'a:3:{i:0;s:3:"NPV";i:1;s:3:"IRR";i:2;s:14:"Payback period";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000938', 'Urutkan tahapan proyek EOR dari perencanaan sampai evaluasi.', 'Arrange the EOR project stages from planning to evaluation.', 'drag', 'PFC000000012', 'Soal Inisialisasi', 'a:5:{i:0;s:15:"Studi kelayakan";i:1;s:9:"Uji pilot";i:2;s:21:"Implementasi lapangan";i:3;s:18:"Monitoring kinerja";i:4;s:22:"Evaluasi ekonomi akhir";}', 'a:5:{i:0;s:17:"Feasibility study";i:1;s:10:"Pilot test";i:2;s:20:"Field implementation";i:3;s:22:"Performance monitoring";i:4;s:25:"Final economic evaluation";}', '', 'a:5:{i:0;s:15:"Studi kelayakan";i:1;s:9:"Uji pilot";i:2;s:21:"Implementasi lapangan";i:3;s:18:"Monitoring kinerja";i:4;s:22:"Evaluasi ekonomi akhir";}', 'a:5:{i:0;s:17:"Feasibility study";i:1;s:10:"Pilot test";i:2;s:20:"Field implementation";i:3;s:22:"Performance monitoring";i:4;s:25:"Final economic evaluation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000939', 'Benarkah proyek EOR selalu memberikan keuntungan ekonomi di semua kondisi harga minyak?', 'Is it true that EOR projects always provide economic benefits at all oil price conditions?', 'yesorno', 'PFC000000012', 'Soal Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000940', 'Proyek EOR menghasilkan arus kas bersih 10 juta USD per tahun selama 5 tahun dengan diskon 10%. Berapa kira-kira NPV-nya (tanpa CAPEX)?', 'An EOR project generates a net cash flow of 10 million USD per year for 5 years with a 10% discount rate. What is the approximate NPV (without CAPEX)?', 'option', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:13:"37,9 juta USD";i:1;s:13:"50,0 juta USD";i:2;s:13:"10,0 juta USD";i:3;s:13:"25,0 juta USD";}', 'a:4:{i:0;s:16:"37.9 million USD";i:1;s:16:"50.0 million USD";i:2;s:16:"10.0 million USD";i:3;s:16:"25.0 million USD";}', '', '37,9 juta USD', '37.9 million USD', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000941', 'Payback period adalah...', 'Payback period is...', 'option', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:56:"Waktu yang dibutuhkan untuk mengembalikan investasi awal";i:1;s:20:"Umur total reservoir";i:2;s:21:"Waktu injeksi polimer";i:3;s:21:"Lama uji laboratorium";}', 'a:4:{i:0;s:49:"The time needed to recover the initial investment";i:1;s:20:"Total reservoir life";i:2;s:22:"Polymer injection time";i:3;s:24:"Laboratory test duration";}', '', 'Waktu yang dibutuhkan untuk mengembalikan investasi awal', 'The time needed to recover the initial investment', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000942', 'Utility factor pada polymer flooding menyatakan...', 'The utility factor in polymer flooding expresses...', 'option', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:54:"Jumlah polimer yang dipakai per barrel minyak tambahan";i:1;s:26:"Jumlah air yang diproduksi";i:2;s:27:"Perbandingan gas dan minyak";i:3;s:23:"Biaya listrik per bulan";}', 'a:4:{i:0;s:56:"The amount of polymer used per incremental barrel of oil";i:1;s:28:"The amount of produced water";i:2;s:17:"The gas-oil ratio";i:3;s:28:"The monthly electricity cost";}', '', 'Jumlah polimer yang dipakai per barrel minyak tambahan', 'The amount of polymer used per incremental barrel of oil', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000943', 'Analisis sensitivitas pada proyek EOR dilakukan untuk...', 'Sensitivity analysis in EOR projects is performed to...', 'option', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:56:"Mengetahui parameter yang paling mempengaruhi keuntungan";i:1;s:27:"Mengubah harga minyak dunia";i:2;s:17:"Menghindari pajak";i:3;s:23:"Menentukan warna grafik";}', 'a:4:{i:0;s:54:"Identify the parameters that most affect profitability";i:1;s:23:"Change world oil prices";i:2;s:11:"Avoid taxes";i:3;s:19:"Choose chart colors";}', '', 'Mengetahui parameter yang paling mempengaruhi keuntungan', 'Identify the parameters that most affect profitability', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000944', 'Jika biaya kimia 5 USD/bbl dan harga minyak 60 USD/bbl, maka biaya kimia menyumbang sekitar... dari pendapatan.', 'If the chemical cost is 5 USD/bbl and the oil price is 60 USD/bbl, the chemical cost accounts for about... of the revenue.', 'option', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:4:"8,3%";i:1;s:5:"0,83%";i:2;s:3:"83%";i:3;s:3:"50%";}', 'a:4:{i:0;s:4:"8.3%";i:1;s:5:"0.83%";i:2;s:3:"83%";i:3;s:3:"50%";}', '', '8,3%', '8.3%', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000945', 'Semakin tinggi tingkat diskonto (discount rate) yang digunakan, maka NPV proyek...', 'The higher the discount rate used, the NPV of the project...', 'option', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:13:"Semakin kecil";i:1;s:13:"Semakin besar";i:2;s:13:"Tidak berubah";i:3;s:22:"Menjadi negatif selalu";}', 'a:4:{i:0;s:15:"Becomes smaller";i:1;s:14:"Becomes larger";i:2;s:17:"Remains unchanged";i:3;s:23:"Always becomes negative";}', '', 'Semakin kecil', 'Becomes smaller', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000946', 'Proyek EOR sebaiknya dilanjutkan ke skala penuh apabila...', 'An EOR project should proceed to full scale when...', 'option', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:67:"Hasil pilot menunjukkan peningkatan produksi dan ekonomi yang layak";i:1;s:26:"Harga minyak sedang rendah";i:2;s:28:"Belum ada studi laboratorium";i:3;s:20:"Tidak ada monitoring";}', 'a:4:{i:0;s:66:"Pilot results show incremental production and acceptable economics";i:1;s:18:"Oil prices are low";i:2;s:33:"No laboratory study has been done";i:3;s:22:"There is no monitoring";}', '', 'Hasil pilot menunjukkan peningkatan produksi dan ekonomi yang layak', 'Pilot results show incremental production and acceptable economics', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000947', 'Program monitoring pada proyek EOR bertujuan untuk...', 'The monitoring program in an EOR project aims to...', 'option', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:60:"Memantau respons reservoir dan mendeteksi masalah lebih awal";i:1;s:23:"Mengurangi jumlah sumur";i:2;s:28:"Menghindari pengambilan data";i:3;s:22:"Menurunkan biaya pajak";}', 'a:4:{i:0;s:52:"Monitor reservoir response and detect problems early";i:1;s:26:"Reduce the number of wells";i:2;s:22:"Avoid data acquisition";i:3;s:16:"Reduce tax costs";}', '', 'Memantau respons reservoir dan mendeteksi masalah lebih awal', 'Monitor reservoir response and detect problems early', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000948', 'Kegagalan proyek EOR sering disebabkan oleh...', 'EOR project failures are often caused by...', 'option', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:64:"Karakterisasi reservoir yang kurang dan desain yang tidak sesuai";i:1;s:19:"Terlalu banyak data";i:2;s:27:"Harga minyak terlalu tinggi";i:3;s:23:"Terlalu banyak simulasi";}', 'a:4:{i:0;s:56:"Poor reservoir characterization and inappropriate design";i:1;s:13:"Too much data";i:2;s:25:"Oil prices being too high";i:3;s:19:"Too much simulation";}', '', 'Karakterisasi reservoir yang kurang dan desain yang tidak sesuai', 'Poor reservoir characterization and inappropriate design', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000949', 'Biaya per barrel minyak tambahan (cost per incremental bbl) dihitung dengan...', 'The cost per incremental barrel is calculated by...', 'option', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:48:"Total biaya proyek dibagi volume minyak tambahan";i:1;s:26:"Volume minyak dikali harga";i:2;s:22:"NPV dibagi umur proyek";i:3;s:17:"CAPEX dikali OPEX";}', 'a:4:{i:0;s:52:"Total project cost divided by incremental oil volume";i:1;s:30:"Oil volume multiplied by price";i:2;s:27:"NPV divided by project life";i:3;s:24:"CAPEX multiplied by OPEX";}', '', 'Total biaya proyek dibagi volume minyak tambahan', 'Total project cost divided by incremental oil volume', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000950', 'NPV positif menunjukkan bahwa proyek...', 'A positive NPV indicates that the project...', 'option', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:66:"Memberikan nilai tambah melebihi tingkat diskonto yang disyaratkan";i:1;s:11:"Pasti gagal";i:2;s:26:"Tidak menghasilkan apa pun";i:3;s:16:"Harus dihentikan";}', 'a:4:{i:0;s:43:"Adds value above the required discount rate";i:1;s:20:"Will definitely fail";i:2;s:16:"Produces nothing";i:3;s:15:"Must be stopped";}', '', 'Memberikan nilai tambah melebihi tingkat diskonto yang disyaratkan', 'Adds value above the required discount rate', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000951', 'Faktor ekonomi paling sensitif pada proyek chemical EOR adalah...', 'The most sensitive economic factor in chemical EOR projects is...', 'option', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:53:"Harga minyak, biaya kimia, dan volume minyak tambahan";i:1;s:12:"Warna minyak";i:2;s:15:"Kedalaman sumur";i:3;s:12:"Jenis casing";}', 'a:4:{i:0;s:52:"Oil price, chemical cost, and incremental oil volume";i:1;s:9:"Oil color";i:2;s:10:"Well depth";i:3;s:11:"Casing type";}', '', 'Harga minyak, biaya kimia, dan volume minyak tambahan', 'Oil price, chemical cost, and incremental oil volume', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
