INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000953', 'Manakah indikator kinerja (KPI) yang dipantau selama proyek EOR?', 'Which key performance indicators (KPIs) are monitored during an EOR project?', 'multi', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:20:"Laju produksi minyak";i:1;s:9:"Water cut";i:2;s:14:"Konsumsi kimia";i:3;s:12:"Warna batuan";}', 'a:4:{i:0;s:19:"Oil production rate";i:1;s:9:"Water cut";i:2;s:20:"Chemical consumption";i:3;s:10:"Rock color";}', '', 'a:3:{i:0;s:20:"Laju produksi minyak";i:1;s:9:"Water cut";i:2;s:14:"Konsumsi kimia";}', 'a:3:{i:0;s:19:"Oil production rate";i:1;s:9:"Water cut";i:2;s:20:"Chemical consumption";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000954', 'Manakah risiko yang perlu dipertimbangkan dalam proyek EOR?', 'Which risks must be considered in an EOR project?', 'multi', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:22:"Fluktuasi harga minyak";i:1;s:35:"Kegagalan injeksi/kerusakan formasi";i:2;s:32:"Ketidakpastian respons reservoir";i:3;s:22:"Perubahan warna minyak";}', 'a:4:{i:0;s:21:"Oil price fluctuation";i:1;s:34:"Injection failure/formation damage";i:2;s:33:"Uncertainty in reservoir response";i:3;s:19:"Change in oil color";}', '', 'a:3:{i:0;s:22:"Fluktuasi harga minyak";i:1;s:35:"Kegagalan injeksi/kerusakan formasi";i:2;s:32:"Ketidakpastian respons reservoir";}', 'a:3:{i:0;s:21:"Oil price fluctuation";i:1;s:34:"Injection failure/formation damage";i:2;s:33:"Uncertainty in reservoir response";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000955', 'Manakah yang termasuk manfaat non-ekonomi dari EOR?', 'Which are non-economic benefits of EOR?', 'multi', 'PFC000000012', 'Final Test Advanced', 'a:4:{i:0;s:36:"Peningkatan ultimate recovery factor";i:1;s:32:"Pemanfaatan kembali lapangan tua";i:2;s:43:"Pengurangan emisi melalui CO2 sequestration";i:3;s:24:"Peningkatan harga minyak";}', 'a:4:{i:0;s:36:"Increase in ultimate recovery factor";i:1;s:29:"Rejuvenation of mature fields";i:2;s:44:"Emission reduction through CO2 sequestration";i:3;s:21:"Increase in oil price";}', '', 'a:3:{i:0;s:36:"Peningkatan ultimate recovery factor";i:1;s:32:"Pemanfaatan kembali lapangan tua";i:2;s:43:"Pengurangan emisi melalui CO2 sequestration";}', 'a:3:{i:0;s:36:"Increase in ultimate recovery factor";i:1;s:29:"Rejuvenation of mature fields";i:2;s:44:"Emission reduction through CO2 sequestration";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000956', 'Urutkan langkah evaluasi ekonomi proyek EOR.', 'Arrange the EOR project economic evaluation steps.', 'drag', 'PFC000000012', 'Final Test Advanced', 'a:5:{i:0;s:32:"Perkiraan volume minyak tambahan";i:1;s:24:"Perkiraan CAPEX dan OPEX";i:2;s:17:"Proyeksi arus kas";i:3;s:19:"Perhitungan NPV/IRR";i:4;s:35:"Analisis sensitivitas dan keputusan";}', 'a:5:{i:0;s:31:"Estimate incremental oil volume";i:1;s:23:"Estimate CAPEX and OPEX";i:2;s:17:"Project cash flow";i:3;s:17:"Calculate NPV/IRR";i:4;s:33:"Sensitivity analysis and decision";}', '', 'a:5:{i:0;s:32:"Perkiraan volume minyak tambahan";i:1;s:24:"Perkiraan CAPEX dan OPEX";i:2;s:17:"Proyeksi arus kas";i:3;s:19:"Perhitungan NPV/IRR";i:4;s:35:"Analisis sensitivitas dan keputusan";}', 'a:5:{i:0;s:31:"Estimate incremental oil volume";i:1;s:23:"Estimate CAPEX and OPEX";i:2;s:17:"Project cash flow";i:3;s:17:"Calculate NPV/IRR";i:4;s:33:"Sensitivity analysis and decision";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000957', 'Urutkan tahapan dari pengumpulan data sampai implementasi EOR di lapangan.', 'Arrange the stages from data acquisition to EOR field implementation.', 'drag', 'PFC000000012', 'Final Test Advanced', 'a:5:{i:0;s:26:"Pengumpulan data reservoir";i:1;s:27:"Karakterisasi dan pemodelan";i:2;s:30:"Screening dan pemilihan metode";i:3;s:28:"Studi laboratorium dan pilot";i:4;s:24:"Implementasi skala penuh";}', 'a:5:{i:0;s:26:"Reservoir data acquisition";i:1;s:29:"Characterization and modeling";i:2;s:30:"Screening and method selection";i:3;s:26:"Laboratory study and pilot";i:4;s:25:"Full-scale implementation";}', '', 'a:5:{i:0;s:26:"Pengumpulan data reservoir";i:1;s:27:"Karakterisasi dan pemodelan";i:2;s:30:"Screening dan pemilihan metode";i:3;s:28:"Studi laboratorium dan pilot";i:4;s:24:"Implementasi skala penuh";}', 'a:5:{i:0;s:26:"Reservoir data acquisition";i:1;s:29:"Characterization and modeling";i:2;s:30:"Screening and method selection";i:3;s:26:"Laboratory study and pilot";i:4;s:25:"Full-scale implementation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000958', 'Benarkah IRR lebih kecil dari tingkat diskonto yang disyaratkan berarti proyek tidak layak?', 'Is it true that an IRR lower than the required discount rate means the project is not feasible?', 'yesorno', 'PFC000000012', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000959', 'Benarkah biaya kimia pada chemical EOR tidak dipengaruhi oleh adsorpsi di reservoir?', 'Is it true that chemical costs in chemical EOR are not affected by reservoir adsorption?', 'yesorno', 'PFC000000012', 'Final Test Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
